# Scene-local source bundle: installed before importing scene support modules.
import importlib.abc as _bundle_abc
import importlib.util as _bundle_util
import json as _bundle_json
import sys as _bundle_sys
from pathlib import Path as _BundlePath

_BUNDLE_SCENE = _BundlePath(__file__).resolve().parent
_BUNDLE_SCRIPTS = _BUNDLE_SCENE.parent
_BUNDLE_PROJECT = next(p for p in _BUNDLE_SCENE.parents if (p / "assets").is_dir())
if str(_BUNDLE_SCRIPTS) not in _bundle_sys.path:
    _bundle_sys.path.insert(0, str(_BUNDLE_SCRIPTS))

_BUNDLE_SOURCES = _bundle_json.loads(r"""{"pcve_project_paths": "\"\"\"Path helpers shared by standalone rigid-scene folders.\"\"\"\nfrom pathlib import Path\nimport sys\n\n\ndef project_root(anchor):\n    anchor = Path(anchor).resolve()\n    candidates = (anchor, *anchor.parents)\n    for candidate in candidates:\n        if (candidate / \"assets\").is_dir() and (candidate / \"clean_scripts\").is_dir():\n            return candidate\n    raise FileNotFoundError(f\"Cannot locate project root above {anchor}; expected assets/ and clean_scripts/\")\n\n\ndef scene_root(anchor):\n    \"\"\"Find the scene folder from argv first, then from the helper's parents.\"\"\"\n    candidates = []\n    if sys.argv and sys.argv[0] not in {\"-\", \"\"}:\n        argv_path = Path(sys.argv[0]).expanduser()\n        if not argv_path.is_absolute():\n            argv_path = Path.cwd() / argv_path\n        candidates.append(argv_path.resolve().parent)\n    anchor = Path(anchor).resolve()\n    candidates.extend(anchor.parents)\n    seen = set()\n    for candidate in candidates:\n        if candidate in seen:\n            continue\n        seen.add(candidate)\n        if any(candidate.glob(\"simulate_*.py\")) and any(candidate.glob(\"render_*.py\")):\n            return candidate\n    raise FileNotFoundError(f\"Cannot locate scene entrypoints above {anchor}\")\n", "pcve_scene_runtime": "\"\"\"Shared command-line and output contracts for PCVE scene entry points.\n\nBoth ``blender -b --python render.py -- ...`` and Python with bpy are supported.\nThis module has no Blender dependency until a renderer finishes.\n\"\"\"\n\nimport argparse\nimport hashlib\nimport json\nimport math\nimport os\nimport random\nimport shutil\nimport sys\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\n_render_args = None\n\n\ndef python_for(role: str) -> Path:\n    override = os.environ.get(\"PCVE_PHYSICS_PYTHON\" if role == \"physics\" else \"PCVE_RENDER_PYTHON\")\n    if override:\n        return Path(override).expanduser()\n    names = (\"sim/python.exe\", \"sim/bin/python\") if role == \"physics\" else (\n        \"render/Scripts/python.exe\", \"render/bin/python\")\n    for base in (ROOT / \".runtime\", ROOT.parent / \"PCVE-ElasticBench/.runtime\"):\n        for name in names:\n            if (base / name).is_file():\n                return base / name\n    if role == \"physics\":\n        # The original Linux setup activates a PyBullet conda environment and\n        # invokes Blender separately. Blender's sys.executable is not Python.\n        candidates = [ROOT.parent / \"miniconda/envs/physics/bin/python\"]\n        if os.environ.get(\"CONDA_PREFIX\"):\n            prefix = Path(os.environ[\"CONDA_PREFIX\"])\n            candidates += [prefix / \"python.exe\", prefix / \"bin/python\"]\n        for name in (\"python3\", \"python\"):\n            if shutil.which(name):\n                candidates.append(Path(shutil.which(name)))\n        for candidate in candidates:\n            if candidate.is_file() and \"blender\" not in candidate.name.lower():\n                return candidate\n    return Path(sys.executable)\n\n\ndef _add(parser, flag, **kwargs):\n    if flag not in parser._option_string_actions:\n        parser.add_argument(flag, **kwargs)\n\n\ndef implementation_hashes(directory):\n    files = list(Path(directory).glob(\"*.py\"))\n    files += [ROOT / \"clean_scripts\" / name for name in (\"pcve_scene_pipeline.py\", \"pcve_edit_dsl.py\")]\n    return {str(path.relative_to(ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()\n            for path in files if path.is_file()}\n\n\ndef case_outputs(folder):\n    \"\"\"Semantic output keys used by the original suite manifests.\"\"\"\n    names = dict(video=\"video.mp4\", ground_truth=\"ground_truth_transforms.json\",\n                 scenario_metadata=\"scenario_metadata.json\", scenario_overrides=\"scenario_overrides.json\",\n                 physics=\"physics_transforms.json\", scenario_input=\"scenario_input.json\", preview=\"preview.png\")\n    return {key: str((Path(folder) / name).resolve()) for key, name in names.items()\n            if (Path(folder) / name).is_file()}\n\n\ndef add_build_arguments(parser):\n    _add(parser, \"--blender\", type=Path, help=\"Blender executable; otherwise use render Python with bpy.\")\n    _add(parser, \"--physics-python\", type=Path, default=python_for(\"physics\"))\n    _add(parser, \"--render-python\", type=Path, default=python_for(\"render\"))\n    _add(parser, \"--engine\", choices=(\"cycles\", \"eevee\"), default=\"cycles\")\n    _add(parser, \"--device\", choices=(\"auto\", \"cpu\"), default=\"auto\")\n    _add(parser, \"--preview-frame\", type=int)\n    _add(parser, \"--fps\", type=int)\n    _add(parser, \"--duration-sec\", type=float)\n    return parser\n\n\ndef render_prefix(args, script: Path) -> list[str]:\n    blender = getattr(args, \"blender\", None) or os.environ.get(\"BLENDER_BIN\")\n    render_python = Path(getattr(args, \"render_python\", python_for(\"render\")))\n    if not blender and render_python == Path(sys.executable):\n        candidates = [ROOT / \"tools/blender-3.6.23-linux-x64/blender\"]\n        if shutil.which(\"blender\"):\n            candidates.append(Path(shutil.which(\"blender\")))\n        blender = next((path for path in candidates if path.is_file()), None)\n    if blender:\n        # Blender otherwise returns success even when the Python script raises.\n        return [str(Path(blender).expanduser()), \"-b\", \"--python-exit-code\", \"1\",\n                \"--python\", str(script), \"--\"]\n    return [str(render_python), str(script)]\n\n\ndef append_render_options(command, args):\n    for name in (\"engine\", \"device\", \"preview_frame\"):\n        flag = \"--\" + name.replace(\"_\", \"-\")\n        value = getattr(args, name, None)\n        if value is not None and flag not in command:\n            command += [flag, str(value)]\n    return command\n\n\ndef parse_render_args(parser, argv=None):\n    global _render_args\n    _add(parser, \"--seed\", type=int, default=0)\n    _add(parser, \"--device\", choices=(\"auto\", \"cpu\"), default=\"auto\")\n    _add(parser, \"--preview-frame\", type=int)\n    _add(parser, \"--fps\", type=int)\n    _add(parser, \"--duration-sec\", type=float)\n    _add(parser, \"--physics-python\", type=Path, default=python_for(\"physics\"))\n    # Renderers without an engine switch currently implement Cycles only.\n    _add(parser, \"--engine\", choices=(\"cycles\",), default=\"cycles\")\n    if argv is None:\n        argv = sys.argv[sys.argv.index(\"--\") + 1:] if \"--\" in sys.argv else sys.argv[1:]\n    _render_args = parser.parse_args(argv)\n    # In the original CLI duration-sec is the real-time clip length. A scene's\n    # optional demo slow-motion preset must not silently multiply that request.\n    if \"--duration-sec\" in argv and \"--slow-motion\" not in argv and hasattr(_render_args, \"slow_motion\"):\n        _render_args.slow_motion = 1\n    random.seed(_render_args.seed)\n    return _render_args\n\n\ndef apply_physics_overrides(args, baseline):\n    \"\"\"Read the original {physics: ...} override format for scalar CLI scenes.\n\n    Bare schedule arrays remain accepted by the older timed-edit escape hatch.\n    Explicit scalar command-line values take precedence over the JSON defaults.\n    \"\"\"\n    path = getattr(args, \"scenario_overrides_json\", None)\n    if path is None:\n        return None\n    payload = json.loads(Path(path).read_text(encoding=\"utf-8\"))\n    if isinstance(payload, list):\n        return Path(path)\n    physics = payload.get(\"physics\", payload)\n    unknown = set(physics) - {*baseline, \"timed_edits\"}\n    if unknown:\n        raise ValueError(f\"Unknown physics overrides: {sorted(unknown)}\")\n    for name, value in physics.items():\n        if name != \"timed_edits\" and getattr(args, name, None) is None:\n            setattr(args, name, value)\n    if physics.get(\"timed_edits\"):\n        target = Path(args.out_dir) / \"timed_edits.json\"\n        target.parent.mkdir(parents=True, exist_ok=True)\n        target.write_text(json.dumps(physics[\"timed_edits\"], indent=2), encoding=\"utf-8\")\n        return target\n    return None\n\n\ndef _matrix(position, q):\n    x, y, z, w = q\n    return [[1-2*(y*y+z*z), 2*(x*y-z*w), 2*(x*z+y*w), position[0]],\n            [2*(x*y+z*w), 1-2*(x*x+z*z), 2*(y*z-x*w), position[1]],\n            [2*(x*z-y*w), 2*(y*z+x*w), 1-2*(x*x+y*y), position[2]],\n            [0, 0, 0, 1]]\n\n\ndef _optional_metrics(value):\n    if isinstance(value, dict):\n        return {key: _optional_metrics(item) for key, item in value.items()}\n    if isinstance(value, list):\n        return [_optional_metrics(item) for item in value]\n    if isinstance(value, float) and not math.isfinite(value):\n        return None\n    return value\n\n\ndef finalize_render_outputs(out: Path, scene_name: str, args, scene=None):\n    \"\"\"Keep scene-specific files and also publish the original PCVE filenames.\"\"\"\n    out = Path(out).resolve()\n    gt_path = out / \"ground_truth_transforms.json\"\n    if gt_path.is_file():\n        gt = json.loads(gt_path.read_text(encoding=\"utf-8\"))\n        gt.setdefault(\"scene\", scene_name)\n        gt.setdefault(\"schema_version\", 1)\n        camera = gt.setdefault(\"camera\", {})\n        camera.setdefault(\"resolution\", list(args.resolution))\n        camera.setdefault(\"sensor_width_mm\", 36.0)\n        if scene is not None and scene.camera is not None:\n            cam = scene.camera\n            camera.update(matrix_world=[list(row) for row in cam.matrix_world],\n                          sensor_width_mm=float(cam.data.sensor_width),\n                          sensor_fit=cam.data.sensor_fit)\n            if cam.data.type == \"ORTHO\":\n                camera.update(projection=\"orthographic\", ortho_scale=float(cam.data.ortho_scale))\n            else:\n                camera.update(projection=\"perspective\", lens_mm=float(cam.data.lens))\n        frames = gt.get(\"frames\", [])\n        # toy_car_bottle retains its raw simulation and render_frames as well.\n        rendered = gt.get(\"render_frames\", [])\n        for index, frame in enumerate(frames):\n            frame.setdefault(\"frame_index\", frame.get(\"frame\", index + 1))\n            frame.setdefault(\"time_sec\", frame.get(\"time\", index / gt.get(\"fps\", 24)))\n            if camera.get(\"matrix_world\") is not None:\n                frame.setdefault(\"camera_matrix_world\", camera[\"matrix_world\"])\n            if index < len(rendered):\n                for name, state in rendered[index].get(\"objects\", {}).items():\n                    raw = frame.get(\"objects\", {}).get(name, {})\n                    frame[name] = dict(raw, present=True, location=state[\"position\"],\n                                       quaternion_xyzw=state[\"quaternion_xyzw\"],\n                                       matrix_world=_matrix(state[\"position\"], state[\"quaternion_xyzw\"]))\n        gt.setdefault(\"frame_start\", 1)\n        gt.setdefault(\"frame_end\", len(frames))\n        if scene_name == \"toy_car_bottle\":\n            layout = gt[\"config\"][\"layout\"]\n            gt[\"objects\"] = {\n                \"car\": {\"object_name\": \"toy_car\", \"dimensions\": [layout[\"car_length\"], layout[\"car_width\"], layout[\"car_height\"]]},\n                \"bottle\": {\"object_name\": \"plastic_bottle\", \"radius\": layout[\"bottle_radius\"], \"height\": layout[\"bottle_height\"]},\n            }\n        # A short diagnostic clip may not contain an impact. Its unavailable\n        # post-contact quality measurements are null; poses must stay finite.\n        for container in (gt, gt.get(\"physics\", {})):\n            if \"quality\" in container:\n                container[\"quality\"] = _optional_metrics(container[\"quality\"])\n        for frame in frames:\n            matrices = [item[\"matrix_world\"] for item in frame.values()\n                        if isinstance(item, dict) and \"matrix_world\" in item\n                        and not (item.get(\"present\") is False and item[\"matrix_world\"] is None)]\n            matrices += [item for key, item in frame.items() if key.endswith(\"_matrix_world\")]\n            for matrix in matrices:\n                if matrix is None:\n                    raise ValueError(\"A present object must have a ground-truth transform\")\n                if not all(math.isfinite(value) for row in matrix for value in row):\n                    raise ValueError(\"Non-finite ground-truth transform\")\n        gt_path.write_text(json.dumps(gt, indent=2, ensure_ascii=False, allow_nan=False), encoding=\"utf-8\")\n    mode = getattr(args, \"mode\", \"preview\")\n    if mode == \"animation\":\n        stem = \"basketball_door\" if scene_name == \"home_basketball_door\" else scene_name\n        source = out / (stem + \".mp4\")\n        target = out / \"video.mp4\"\n        if source.is_file() and not (scene_name == \"uneven_ground_ball\" and getattr(args, \"label\", False)):\n            shutil.copy2(source, target)\n        if not target.is_file():\n            raise FileNotFoundError(f\"Animation did not produce {target}\")\n    refresh_alias = scene_name in (\"home_basketball_door\", \"pot_lid_drop\") or (\n        scene_name == \"toy_car_bottle\" and getattr(args, \"preview_frame\", None) is None)\n    if mode == \"preview\" and (refresh_alias or not (out / \"preview.png\").is_file()):\n        number = getattr(args, \"preview_frame\", None) or 1\n        candidates = [out / f\"preview_frame_{number:04d}.png\", out / \"first_frame.png\"]\n        candidates += sorted(out.glob(\"preview_frame_*.png\"))\n        source = next((p for p in candidates if p.is_file()), None)\n        if source is None:\n            raise FileNotFoundError(f\"Preview did not produce an image in {out}\")\n        shutil.copy2(source, out / \"preview.png\")\n\n\ndef run_renderer(main, scene_name):\n    global _render_args\n    _render_args = None\n    main()\n    if _render_args is not None:\n        import bpy\n        finalize_render_outputs(_render_args.out_dir, scene_name, _render_args, bpy.context.scene)\n", "pcve_blender_compat": "\"\"\"Small Blender 3.6/4.x API differences used by the scene renderers.\"\"\"\n\nSOCKET_NAMES = {\n    \"Coat Weight\": \"Clearcoat\", \"Coat Roughness\": \"Clearcoat Roughness\",\n    \"Specular IOR Level\": \"Specular\", \"Transmission Weight\": \"Transmission\",\n    \"Emission Color\": \"Emission\", \"Sheen Weight\": \"Sheen\",\n    \"Sheen Roughness\": \"Roughness\", \"Subsurface Weight\": \"Subsurface\",\n}\n\n\ndef shader_socket(node, name):\n    socket = node.inputs.get(name)\n    if socket is None:\n        socket = node.inputs.get(SOCKET_NAMES.get(name, name))\n    if socket is None:\n        raise KeyError(f\"{node.name}: missing shader input {name}\")\n    return socket\n\n\ndef set_shader_input(node, name, value):\n    socket = shader_socket(node, name)\n    if socket.type == \"VALUE\" and isinstance(value, (tuple, list)):\n        value = sum(value[:3]) / 3\n    socket.default_value = value\n\n\ndef eevee_engine():\n    import bpy\n    return \"BLENDER_EEVEE_NEXT\" if bpy.app.version >= (4, 2, 0) else \"BLENDER_EEVEE\"\n\n\ndef set_eevee_property(settings, name, value):\n    parts = name.split(\".\")\n    for part in parts[:-1]:\n        if not hasattr(settings, part):\n            return\n        settings = getattr(settings, part)\n    if hasattr(settings, parts[-1]):\n        setattr(settings, parts[-1], value)\n\n\ndef set_color_property(settings, name, value):\n    try:\n        setattr(settings, name, value)\n    except (TypeError, ValueError):\n        candidates = (\"Filmic\", \"Standard\") if name == \"view_transform\" else (\"Medium High Contrast\", \"None\")\n        for candidate in candidates:\n            try:\n                setattr(settings, name, candidate)\n                return\n            except (TypeError, ValueError):\n                continue\n        raise\n\n\ndef configure_cycles_device(bpy, scene, requested):\n    scene.cycles.device = \"CPU\"\n    scene.render.threads_mode = \"FIXED\"\n    scene.render.threads = 4\n    if requested == \"cpu\":\n        return \"CPU\"\n    prefs = bpy.context.preferences.addons[\"cycles\"].preferences\n    for backend in (\"OPTIX\", \"CUDA\", \"HIP\", \"METAL\"):\n        try:\n            prefs.compute_device_type = backend\n            prefs.get_devices()\n            found = [device for device in prefs.devices if device.type == backend]\n            if found:\n                for device in prefs.devices:\n                    device.use = device.type == backend\n                scene.cycles.device = \"GPU\"\n                return \"GPU\"\n        except (TypeError, RuntimeError, ValueError):\n            continue\n    return \"CPU\"\n", "pcve_legacy_scene": "\"\"\"Original batch/suite workflow for scenes backed by a scenario.json file.\"\"\"\n\nimport argparse\nimport hashlib\nimport importlib\nimport json\nimport random\nimport shutil\nimport subprocess\nimport time\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\n\nfrom pcve_scene_runtime import ROOT, add_build_arguments, append_render_options, render_prefix, implementation_hashes, case_outputs\n\nimport pcve_edit_dsl as dsl\n\n\nSCRIPTS = {\n    \"home_basketball_door\": (\"render_home_basketball_door.py\", \"simulate_home_basketball_door.py\"),\n    \"pot_lid_drop\": (\"render_pot_lid_drop.py\", \"simulate_pot_lid_drop.py\"),\n    \"toy_car_bottle\": (\"render_toy_car_bottle.py\", \"simulate_toy_car_bottle.py\"),\n}\n\n\ndef write_json(path, data):\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(data, indent=2, ensure_ascii=False, allow_nan=False), encoding=\"utf-8\")\n\n\ndef parser(scene, batch=False):\n    p = argparse.ArgumentParser(description=f\"Build {'randomized samples' if batch else 'a source/edit suite'} for {scene}.\")\n    p.add_argument(\"--out-root\", type=Path, default=ROOT / \"renders\" / (f\"batch_{scene}\" if batch else f\"pcve_{scene}_suite\"))\n    p.add_argument(\"--resolution\", nargs=2, type=int, default=[1280, 720])\n    p.add_argument(\"--fps\", type=int, default=24)\n    p.add_argument(\"--duration-sec\", type=float, default=4.0)\n    p.add_argument(\"--samples\", type=int, default=32)\n    p.add_argument(\"--engine\", choices=(\"cycles\",), default=\"cycles\")\n    p.add_argument(\"--mode\", choices=(\"preview\", \"animation\"), default=\"preview\" if batch else \"animation\")\n    p.add_argument(\"--skip-existing\", action=\"store_true\")\n    p.add_argument(\"--dry-run\", action=\"store_true\")\n    p.add_argument(\"--verbose-render\", action=\"store_true\")\n    p.add_argument(\"--simulate-only\", action=\"store_true\")\n    if batch:\n        p.add_argument(\"--count\", type=int, default=4)\n        p.add_argument(\"--start-index\", type=int, default=0)\n        p.add_argument(\"--seed-base\", type=int, default=7200)\n    else:\n        p.add_argument(\"--cases\", nargs=\"+\")\n        p.add_argument(\"--clean-stale-cases\", action=\"store_true\")\n    return add_build_arguments(p)\n\n\ndef scene_directory(scene):\n    candidates = (ROOT / \"clean_scripts\" / scene, ROOT / \"clean_scripts\" / scene)\n    for directory in candidates:\n        if directory.is_dir():\n            return directory\n    raise FileNotFoundError(f\"No scene directory found for {scene}: {candidates}\")\n\n\ndef command_for(scene, folder, args, seed, overrides):\n    render, simulate = SCRIPTS[scene]\n    directory = scene_directory(scene)\n    if args.simulate_only:\n        command = [str(args.physics_python), str(directory / simulate), \"--out\", str(folder / \"physics_transforms.json\")]\n    else:\n        command = render_prefix(args, directory / render)\n        command += [\"--out-dir\", str(folder), \"--mode\", args.mode,\n                    \"--resolution\", *map(str, args.resolution), \"--samples\", str(args.samples),\n                    \"--physics-python\", str(args.physics_python), \"--seed\", str(seed)]\n        append_render_options(command, args)\n    command += [\"--fps\", str(args.fps), \"--duration-sec\", str(args.duration_sec)]\n    if overrides is not None:\n        command += [\"--scenario-overrides-json\", str(overrides)]\n    return command\n\n\ndef run_case(scene, folder, args, seed, override):\n    folder = folder.resolve()\n    overrides = folder / \"scenario_overrides.json\" if override else None\n    command = command_for(scene, folder, args, seed, overrides)\n    if args.dry_run:\n        print(subprocess.list2cmdline(command))\n        return {\"status\": \"dry_run\"}\n    implementation = implementation_hashes(scene_directory(scene))\n    payload = dict(override=override, implementation=implementation, seed=seed, fps=args.fps,\n                   duration=args.duration_sec, mode=args.mode, samples=args.samples,\n                   resolution=args.resolution, engine=args.engine, device=args.device,\n                   preview_frame=args.preview_frame, simulation_only=args.simulate_only)\n    fp = hashlib.sha256(json.dumps(payload, sort_keys=True).encode()).hexdigest()\n    status_path = folder / \"run_status.json\"\n    required = [\"physics_transforms.json\"] if args.simulate_only else [\n        \"ground_truth_transforms.json\", \"scenario_metadata.json\",\n        \"video.mp4\" if args.mode == \"animation\" else \"preview.png\"]\n    if args.skip_existing and status_path.is_file():\n        previous = json.loads(status_path.read_text(encoding=\"utf-8\"))\n        if previous.get(\"fingerprint\") == fp and all((folder / p).is_file() for p in required):\n            return dict(previous, status=\"skipped_existing\")\n    if overrides is not None:\n        write_json(overrides, override)\n    folder.mkdir(parents=True, exist_ok=True)\n    start = time.perf_counter()\n    if args.verbose_render:\n        subprocess.run(command, check=True)\n    else:\n        with (folder / \"render.log\").open(\"w\", encoding=\"utf-8\") as log:\n            subprocess.run(command, stdout=log, stderr=subprocess.STDOUT, check=True)\n    for name in required:\n        if not (folder / name).is_file():\n            raise FileNotFoundError(folder / name)\n    status = dict(status=\"completed\", valid=True, fingerprint=fp, simulation_only=args.simulate_only,\n                  render_mode=args.mode, elapsed_sec=round(time.perf_counter() - start, 3),\n                  outputs=case_outputs(folder))\n    write_json(status_path, status)\n    return status\n\n\ndef batch_main(scene, argv=None):\n    args = parser(scene, batch=True).parse_args(argv)\n    args.out_root = args.out_root.resolve()\n    if args.count < 1 or args.start_index < 0:\n        raise ValueError(\"Count must be positive and start index nonnegative\")\n    directory = scene_directory(scene)\n    import sys\n    if str(directory.parent) not in sys.path:\n        sys.path.insert(0, str(directory.parent))\n    vocab = importlib.import_module(f\"{scene}.edit_vocab\").VOCAB\n    manifest = dict(schema_version=1, scene=scene, mode=args.mode, count=args.count,\n                    start_index=args.start_index, seed_base=args.seed_base, samples=[])\n    for offset in range(args.count):\n        index = args.start_index + offset\n        seed = args.seed_base + index\n        rng = random.Random(seed)\n        params = dict(vocab.baseline_physics)\n        for binding in vocab.sim_bindings.values():\n            if isinstance(binding, dsl.SimBinding) and isinstance(params[binding.key], (int, float)):\n                params[binding.key] *= rng.uniform(.8, 1.2)\n        folder = args.out_root / f\"sample_{index:04d}\"\n        result = run_case(scene, folder, args, seed, {\"physics\": params})\n        manifest[\"samples\"].append(dict(sample_index=index, seed=seed, params=params,\n                                         out_dir=str(folder), **result))\n        if not args.dry_run:\n            write_json(args.out_root / \"batch_manifest.json\", manifest)\n\n\ndef suite_main(scene, argv=None):\n    args = parser(scene).parse_args(argv)\n    args.out_root = args.out_root.resolve()\n    directory = scene_directory(scene)\n    import sys\n    if str(directory.parent) not in sys.path:\n        sys.path.insert(0, str(directory.parent))\n    module = importlib.import_module(f\"{scene}.edit_vocab\")\n    vocab = module.VOCAB\n    source_id = f\"{scene}_baseline\"\n    cases = list(module.EDIT_CASES)\n    if args.cases:\n        unknown = set(args.cases) - {source_id, *[name for name, _ in cases]}\n        if unknown:\n            raise ValueError(f\"Unknown cases: {sorted(unknown)}\")\n        cases = [(name, instruction) for name, instruction in cases if name in args.cases]\n    if args.clean_stale_cases and not args.dry_run:\n        keep = {source_id, *[name for name, _ in module.EDIT_CASES]}\n        for folder in (args.out_root / \"cases\").glob(\"*\"):\n            if folder.is_dir() and folder.name not in keep:\n                if not folder.resolve().is_relative_to(args.out_root):\n                    raise ValueError(f\"Unsafe case directory: {folder}\")\n                shutil.rmtree(folder)\n    manifest = dict(schema_version=3, suite_name=f\"pcve_{scene}_suite\", scene=scene,\n                    baseline_physics=vocab.baseline_physics, total_frames=round(args.fps * args.duration_sec),\n                    fps=args.fps, duration_sec=args.duration_sec, physical_duration_sec=args.duration_sec,\n                    playback_duration_sec=args.duration_sec, slow_motion=1, sample_fps=args.fps,\n                    samples=args.samples, resolution=args.resolution, source=None, edits=[])\n    path = args.out_root / \"suite_manifest.json\"\n    for index, (case_id, instruction) in enumerate([(source_id, None), *cases]):\n        folder = args.out_root / \"cases\" / case_id\n        record = dict(case_id=case_id, kind=\"edit\" if instruction else \"source\",\n                      case_dir=str(folder), seed=7300 + index, status=\"pending\")\n        override = None\n        if instruction:\n            edit = dsl.parse(instruction, vocab)\n            override = {\"physics\": dsl.to_scenario_override(edit, vocab)}\n            record.update(source_case_id=source_id, edit_dsl=instruction,\n                          edit_summary=\"Change the declared physical parameter and simulate the resulting rigid-body interaction.\",\n                          applies_from_frame=dsl.starts_at_frame(edit), prompts=dsl.make_prompts(edit, vocab),\n                          physics_diff={f\"{edit.property_name} ({edit.object_id})\": {\n                              \"from\": dsl.baseline_value_for(edit, vocab), \"to\": dsl.resolved_to_value(edit, vocab)},\n                              \"timing\": dsl.timing_diff(edit, vocab)})\n            manifest[\"edits\"].append(record)\n        else:\n            record[\"description\"] = module.DESCRIPTION\n            manifest[\"source\"] = record\n        if not args.dry_run:\n            prompts = dict(schema_version=2 if instruction else 1, **record)\n            if not instruction:\n                prompts[\"prompts\"] = module.DESCRIPTION\n            write_json(folder / \"prompts.json\", prompts)\n            write_json(path, manifest)\n        try:\n            record.update(run_case(scene, folder, args, record[\"seed\"], override))\n        except Exception:\n            record[\"status\"] = \"failed\"\n            write_json(path, manifest)\n            raise\n        if not args.dry_run:\n            write_json(path, manifest)\n", "pcve_render_quality": "\"\"\"Appearance render setup only; no simulation settings or shared project edits.\"\"\"\n\nimport sys\nfrom pathlib import Path\nsys.path.insert(0, str(Path(__file__).resolve().parents[2]))\nfrom pcve_blender_compat import (shader_socket, set_shader_input, eevee_engine, set_eevee_property, set_color_property)\ndef configure_renderer(bpy,scene,args):\n    scene.render.engine=eevee_engine() if args.engine=='eevee' else 'CYCLES'\n    if args.engine=='eevee':\n        set_eevee_property(scene.eevee, 'taa_render_samples', args.samples);set_eevee_property(scene.eevee, 'use_raytracing', False)\n        set_eevee_property(scene.eevee, 'ray_tracing_options.resolution_scale', '2');set_eevee_property(scene.eevee, 'ray_tracing_options.screen_trace_quality', 0.6)\n        set_eevee_property(scene.eevee, 'use_gtao', True);set_eevee_property(scene.eevee, 'gtao_distance', 0.2);set_eevee_property(scene.eevee, 'gtao_quality', 1.0)\n        set_eevee_property(scene.eevee, 'shadow_ray_count', 1);set_eevee_property(scene.eevee, 'shadow_step_count', 8)\n    else:\n        scene.cycles.samples=args.samples;scene.cycles.use_denoising=True;scene.cycles.max_bounces=8;scene.cycles.diffuse_bounces=4;scene.cycles.glossy_bounces=4\n        scene.cycles.adaptive_threshold=.008;scene.cycles.seed=19;scene.render.use_persistent_data=True\n        # Default 1.5 px pixel filter softens fine background detail; 1.0 keeps the\n        # scanned bookshelf textures crisp without aliasing the suspension threads.\n        scene.cycles.filter_width=1.0\n        scene.cycles.device='CPU'\n        if args.device=='auto':\n            prefs=bpy.context.preferences.addons['cycles'].preferences\n            try:\n                prefs.compute_device_type='CUDA';prefs.get_devices();available=[dev for dev in prefs.devices if dev.type=='CUDA']\n                for dev in prefs.devices:dev.use=(dev.type=='CUDA')\n                if available:\n                    scene.cycles.device='GPU';scene.cycles.denoiser='OPTIX' if any(dev.type=='OPTIX' for dev in prefs.devices) else 'OPENIMAGEDENOISE'\n                    print('[render] CUDA: '+', '.join(dev.name for dev in available),flush=True)\n            except Exception as exc:\n                scene.cycles.device='CPU';scene.cycles.denoiser='OPENIMAGEDENOISE'\n                print('[render] CPU fallback: '+str(exc),flush=True)\n        return scene.cycles.device\n    return 'GPU'\n\n\ndef configure_color(scene):\n    set_color_property(scene.view_settings, 'view_transform', 'AgX');set_color_property(scene.view_settings, 'look', 'AgX - Medium High Contrast');scene.view_settings.exposure=-.22\n\n\ndef prepare_eevee(bpy,scene,moving):\n    if scene.render.engine!=eevee_engine() or bpy.app.version<(4,2,0):return\n    for light in bpy.data.lights:light.use_shadow_jitter=False\n    scene.use_nodes=True;nodes=scene.node_tree.nodes;links=scene.node_tree.links;nodes.clear()\n    layers=nodes.new('CompositorNodeRLayers');denoise=nodes.new('CompositorNodeDenoise');denoise.use_hdr=True\n    composite=nodes.new('CompositorNodeComposite');links.new(layers.outputs['Image'],denoise.inputs['Image']);links.new(denoise.outputs['Image'],composite.inputs['Image'])\n    probe_data=bpy.data.lightprobes.new('Static room irradiance','VOLUME');probe_data.resolution_x=6;probe_data.resolution_y=4;probe_data.resolution_z=4;probe_data.bake_samples=32;probe_data.surfel_density=10\n    probe=bpy.data.objects.new('Static room irradiance',probe_data);scene.collection.objects.link(probe);probe.location=[.2,.5,1.3];probe.scale=[2.5,2.2,1.6]\n    dynamic=list(moving)\n    for obj in list(dynamic):dynamic.extend(obj.children_recursive)\n    dynamic=list(dict.fromkeys(dynamic));previous=[obj.hide_render for obj in dynamic]\n    try:\n        for obj in dynamic:obj.hide_render=True\n        bpy.context.view_layer.objects.active=probe;probe.select_set(True)\n        print('[render] Baking static room indirect light',flush=True);bpy.ops.object.lightprobe_cache_bake(subset='ALL')\n    finally:\n        for obj,hidden in zip(dynamic,previous):obj.hide_render=hidden\n", "scene_support": "", "scene_support.volleyball_corner_rebound.camera_rig": "\"\"\"Camera setup shared by every case; fixed mode has no camera animation.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport bpy\nimport math\nfrom mathutils import Vector\n\ndef animate_camera(camera, rows, config):\n    camera.animation_data_clear()\n    camera.data.animation_data_clear()\n    camera.location=config['camera_location']\n    camera.data.lens=config['lens_mm']\n    camera.rotation_mode='QUATERNION'\n    if config.get('camera_mode','fixed')=='fixed':\n        # Clear both object and lens actions so an older tracking setup cannot\n        # survive a switch to the locked camera, even in a saved Blender file.\n        focus=Vector(config['camera_target'])\n        rotation=(focus-camera.location).to_track_quat('-Z','Y')\n        camera.rotation_quaternion=rotation\n        return [{'frame_index':row['frame_index'],'location':list(camera.location),\n            'quaternion_xyzw':[rotation.x,rotation.y,rotation.z,rotation.w],\n            'focus':list(focus),'lens_mm':camera.data.lens} for row in rows]\n    alpha=float(config.get('tracking_smoothing',.65))\n    if not 0<alpha<=1:\n        raise ValueError('tracking_smoothing must be in (0,1]')\n    focus=None\n    poses=[]\n    previous=None\n    speed=math.hypot(*rows[0].get('ball_linear_velocity',[0,0,0]))\n    reference=float(config.get('tracking_speed_reference',5.85))\n    time_scale=min(1,reference/max(speed,.001))\n    for row in rows:\n        if config.get('camera_mode','fixed')=='tracking':\n            x,y,z=row['ball_location']\n            moving=Vector((x,y,max(.25,z-.15)))\n            hold=float(config.get('tracking_hold_sec',0))*time_scale\n            blend=max(.001,float(config.get('tracking_blend_sec',.45))*time_scale)\n            weight=max(0,min(1,(row['time_sec']-hold)/blend))\n            weight=weight*weight*(3-2*weight)\n            desired=Vector(config['camera_target']).lerp(moving,weight)\n            focus=desired if focus is None else focus.lerp(desired,alpha)\n        else:\n            focus=Vector(config['camera_target'])\n        rotation=(focus-camera.location).to_track_quat('-Z','Y')\n        if previous is not None and rotation.dot(previous)<0:\n            rotation.negate()\n        camera.rotation_quaternion=rotation\n        if config.get('adaptive_lens',False):\n            distance=(Vector(row['ball_location'])-camera.location).length\n            camera.data.lens=max(30,min(70,.055*36*distance/.21))\n            camera.data.keyframe_insert('lens',frame=row['frame_index'])\n        camera.keyframe_insert('rotation_quaternion',frame=row['frame_index'])\n        poses.append({'frame_index':row['frame_index'],'location':list(camera.location),\n            'quaternion_xyzw':[rotation.x,rotation.y,rotation.z,rotation.w],\n            'focus':list(focus),'lens_mm':camera.data.lens})\n        previous=rotation.copy()\n    for curve in camera.animation_data.action.fcurves:\n        for point in curve.keyframe_points:\n            point.interpolation='LINEAR'\n    if camera.data.animation_data:\n        for curve in camera.data.animation_data.action.fcurves:\n            for point in curve.keyframe_points:\n                point.interpolation='LINEAR'\n    return poses\n", "scene_support.volleyball_corner_rebound.scene_config": "\"\"\"Single source of truth for simulation, edit vocabulary and visual geometry.\"\"\"\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport copy\nimport json\nimport math\nfrom pathlib import Path\n\nROOT = _PCVE_ROOT\nHERE = next((p for p in (ROOT / 'new-scripts' / 'volleyball_corner_rebound', ROOT / 'clean_scripts' / 'rigid_rigid' / 'volleyball_corner_rebound') if p.is_dir()), ROOT / 'clean_scripts' / 'rigid_rigid' / 'volleyball_corner_rebound')\nSCENARIO_DIR = ROOT / 'assets' / 'scenarios' / 'volleyball_corner_rebound'\nMODELS = ROOT / 'assets' / 'models'\n\n# Scene-control keys carry the in-run edit schedule rather than a measurement\n# of the room: they are absent from scenario.json, and every case has one\n# (empty unless the case carries a timed edit). Defaulting them before the\n# override patch is applied is what makes a schedule a legal physics override.\nSCENE_CONTROL_DEFAULTS = {'timed_edits': []}\n\ndef load_scenario(overrides=None):\n    result = json.loads((SCENARIO_DIR / 'scenario.json').read_text(encoding='utf-8'))\n    for key, value in SCENE_CONTROL_DEFAULTS.items():\n        result['physics'].setdefault(key, copy.deepcopy(value))\n    if overrides is not None:\n        patch = json.loads(Path(overrides).read_text(encoding='utf-8')) if isinstance(overrides, (str, Path)) else copy.deepcopy(overrides)\n        for section, values in patch.items():\n            if section not in result or not isinstance(values, dict):\n                raise ValueError(f'Unsupported scenario section: {section}')\n            unknown = set(values) - set(result[section])\n            if unknown:\n                raise ValueError(f'Unknown {section} keys: {sorted(unknown)}')\n            result[section].update(values)\n    p = result['physics']\n    for key in ('fps', 'duration_sec', 'substeps_per_frame', 'ball_mass', 'ball_radius', 'ball_initial_speed'):\n        if not math.isfinite(float(p[key])) or p[key] <= 0:\n            raise ValueError(f'{key} must be positive and finite')\n    for key in ('ball_restitution', 'floor_restitution', 'wall_restitution'):\n        if not 0 <= p[key] <= 1:\n            raise ValueError(f'{key} must be in [0, 1]')\n    for key in ('ball_friction', 'ball_rolling_friction', 'ball_spinning_friction', 'floor_friction', 'floor_rolling_friction', 'wall_friction', 'linear_damping', 'angular_damping'):\n        if not math.isfinite(float(p[key])) or p[key] < 0:\n            raise ValueError(f'{key} must be nonnegative and finite')\n    if len(p['room_size']) != 3 or min(p['room_size']) <= 0:\n        raise ValueError('room_size must contain three positive dimensions')\n    if len(p['launch_direction']) != 3 or not all(math.isfinite(v) for v in p['launch_direction']) or math.hypot(*p['launch_direction']) == 0:\n        raise ValueError('Nonzero finite launch_direction XYZ required')\n    if len(p['ball_initial_angular_velocity']) != 3 or not all(math.isfinite(v) for v in p['ball_initial_angular_velocity']):\n        raise ValueError('Finite initial angular velocity XYZ required')\n    if len(p['ball_initial_location']) != 3 or any(not math.isfinite(v) or not p['ball_radius'] < v < extent-p['ball_radius'] for v, extent in zip(p['ball_initial_location'], p['room_size'])):\n        raise ValueError('Ball starts outside the room or intersects a wall')\n    if 2*p['ball_radius'] >= p['room_size'][2]:\n        raise ValueError('Ball must fit below the ceiling')\n    return result\n\ndef write_json(path, value):\n    path = Path(path)\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(value, ensure_ascii=False, indent=2, allow_nan=False), encoding='utf-8')\n\ndef runtime(kind):\n    relative = 'render/Scripts/python.exe' if kind == 'render' else 'sim/python.exe'\n    for root in (ROOT, ROOT.parent / 'PCVE-ElasticBench'):\n        path = root / '.runtime' / relative\n        if path.is_file():\n            return str(path)\n    raise FileNotFoundError(f'No {kind} Python runtime; use an environment with bpy/pybullet')\n", "scene_support.volleyball_corner_rebound.scene_environment": "\"\"\"Photographic materials and metre-scale architectural room, authored locally.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport math\nfrom pathlib import Path\nROOT = _PCVE_ROOT\nimport bpy\nfrom mathutils import Vector\nfrom scene_config import MODELS\nfrom scene_geometry import (AC_BACK_GAP, AC_CENTER, AC_HEIGHT, AC_WIDTH, CABINET_CENTER,\n    CABINET_SIZE, SPARE_BALL_CENTERS, SPARE_BALL_RADIUS, WINDOW_CENTER_Y)\n\n# cafe_wall_pictures.glb stacks three pictures on one shared 0.49 x 0.33 m mesh that\n# differ only in texture, so choosing the artwork is a name lookup: wall and frame\n# geometry stay put.  Picture 1 is a photo-real window-and-coffee-jar still life, its\n# dark frame and busy interior collapsing into a brown smudge at the size the far\n# camera gives it; picture 3 is a coffee-bean owl on cream that vanishes against the\n# pale wall; picture 2 is a copper mug on a flat blush ground and still reads as a\n# picture from across the room.\nPICTURE_MESH = 'wall_picture_2'\n\ndef material(name, color, roughness=.6, bump=.0):\n    mat = bpy.data.materials.new(name)\n    mat.diffuse_color = (*color, 1)\n    mat.use_nodes = True\n    nodes, links = mat.node_tree.nodes, mat.node_tree.links\n    bsdf = nodes.get('Principled BSDF')\n    bsdf.inputs['Base Color'].default_value = (*color, 1)\n    bsdf.inputs['Roughness'].default_value = roughness\n    if bump:\n        coord = nodes.new('ShaderNodeTexCoord')\n        noise = nodes.new('ShaderNodeTexNoise')\n        noise.inputs['Scale'].default_value = 170\n        noise.inputs['Detail'].default_value = 2\n        links.new(coord.outputs['Object'], noise.inputs['Vector'])\n        node = nodes.new('ShaderNodeBump')\n        node.inputs['Strength'].default_value = .22\n        node.inputs['Distance'].default_value = bump\n        links.new(noise.outputs['Fac'], node.inputs['Height'])\n        links.new(node.outputs['Normal'], bsdf.inputs['Normal'])\n    return mat\n\ndef cube(name, center, size, mat, bevel=0):\n    bpy.ops.mesh.primitive_cube_add(size=1, location=center)\n    obj = bpy.context.object\n    obj.name = name\n    obj.dimensions = size\n    bpy.ops.object.transform_apply(location=False, rotation=False, scale=True)\n    obj.data.materials.append(mat)\n    if bevel:\n        mod = obj.modifiers.new('Soft manufactured edges', 'BEVEL')\n        mod.width, mod.segments = bevel, 3\n        obj.modifiers.new('Weighted normals', 'WEIGHTED_NORMAL')\n    return obj\n\ndef aim(obj, point):\n    obj.rotation_euler = (Vector(point)-obj.location).to_track_quat('-Z','Y').to_euler()\n\ndef area(name, pos, target, power, size, color=(1,.89,.75)):\n    data = bpy.data.lights.new(name, 'AREA')\n    data.energy, data.shape, data.size, data.color = power, 'DISK', size, color\n    # These broad sources approximate bounced daylight, not visible fixtures.\n    # The HDR and room geometry provide the actual glass reflections.\n    data.specular_factor=0\n    obj = bpy.data.objects.new(name,data)\n    bpy.context.collection.objects.link(obj)\n    obj.location = pos\n    obj.visible_glossy=False\n    aim(obj,target)\n    return obj\n\ndef floor_material(path):\n    mat = material('Oak boards / scanned worn wood', (.32,.19,.09), .48)\n    nodes, links = mat.node_tree.nodes, mat.node_tree.links\n    bsdf = nodes.get('Principled BSDF')\n    uv = nodes.new('ShaderNodeTexCoord')\n    sep = nodes.new('ShaderNodeSeparateXYZ')\n    links.new(uv.outputs['Object'],sep.inputs[0])\n    combine = nodes.new('ShaderNodeCombineXYZ')\n    for axis in ('X','Y'):\n        scale = nodes.new('ShaderNodeMath')\n        scale.operation = 'MULTIPLY'\n        scale.inputs[1].default_value = .62\n        links.new(sep.outputs[axis],scale.inputs[0])\n        links.new(scale.outputs[0],combine.inputs[axis])\n    image = nodes.new('ShaderNodeTexImage')\n    image.image = bpy.data.images.load(str(path), check_existing=True)\n    image.extension = 'REPEAT'\n    links.new(combine.outputs[0],image.inputs['Vector'])\n    links.new(image.outputs['Color'],bsdf.inputs['Base Color'])\n    bump = nodes.new('ShaderNodeBump')\n    bump.inputs['Strength'].default_value = .18\n    bump.inputs['Distance'].default_value = .002\n    links.new(image.outputs['Color'],bump.inputs['Height'])\n    links.new(bump.outputs['Normal'],bsdf.inputs['Normal'])\n    return mat\n\ndef terrazzo_material():\n    mat=material('Fine warm-grey terrazzo / 1 m slabs',(.25,.265,.26),.49)\n    nodes,links=mat.node_tree.nodes,mat.node_tree.links\n    bsdf=nodes.get('Principled BSDF')\n    coord=nodes.new('ShaderNodeTexCoord')\n    chips=nodes.new('ShaderNodeTexVoronoi')\n    chips.inputs['Scale'].default_value=35\n    chips.distance='EUCLIDEAN'\n    links.new(coord.outputs['Object'],chips.inputs['Vector'])\n    gate=nodes.new('ShaderNodeMath')\n    gate.operation='LESS_THAN'\n    gate.inputs[1].default_value=.36\n    links.new(chips.outputs['Distance'],gate.inputs[0])\n    palette=nodes.new('ShaderNodeValToRGB')\n    palette.color_ramp.interpolation='CONSTANT'\n    for index,(position,color) in enumerate(((0,(.055,.065,.06,1)),(.35,(.24,.19,.14,1)),(.5,(.43,.45,.43,1)),(.7,(.62,.60,.54,1)))):\n        element=palette.color_ramp.elements[index] if index<2 else palette.color_ramp.elements.new(position)\n        element.position=position\n        element.color=color\n    links.new(chips.outputs['Color'],palette.inputs[0])\n    mix=nodes.new('ShaderNodeMixRGB')\n    mix.inputs[1].default_value=(.25,.265,.26,1)\n    links.new(gate.outputs[0],mix.inputs[0])\n    links.new(palette.outputs['Color'],mix.inputs[2])\n    separate=nodes.new('ShaderNodeSeparateXYZ')\n    links.new(coord.outputs['Object'],separate.inputs[0])\n    seams=[]\n    for axis in ('X','Y'):\n        fract=nodes.new('ShaderNodeMath')\n        fract.operation='FRACT'\n        links.new(separate.outputs[axis],fract.inputs[0])\n        seam=nodes.new('ShaderNodeMath')\n        seam.operation='LESS_THAN'\n        seam.inputs[1].default_value=.003\n        links.new(fract.outputs[0],seam.inputs[0])\n        seams.append(seam)\n    combine=nodes.new('ShaderNodeMath')\n    combine.operation='MAXIMUM'\n    for index,seam in enumerate(seams):\n        links.new(seam.outputs[0],combine.inputs[index])\n    grout=nodes.new('ShaderNodeMixRGB')\n    links.new(combine.outputs[0],grout.inputs[0])\n    links.new(mix.outputs[0],grout.inputs[1])\n    grout.inputs[2].default_value=(.11,.12,.11,1)\n    links.new(grout.outputs[0],bsdf.inputs['Base Color'])\n    grain=nodes.new('ShaderNodeTexNoise')\n    grain.inputs['Scale'].default_value=220\n    grain.inputs['Detail'].default_value=2\n    links.new(coord.outputs['Object'],grain.inputs['Vector'])\n    bump=nodes.new('ShaderNodeBump')\n    bump.inputs['Strength'].default_value=.13\n    bump.inputs['Distance'].default_value=.00022\n    links.new(grain.outputs['Fac'],bump.inputs['Height'])\n    links.new(bump.outputs['Normal'],bsdf.inputs['Normal'])\n    return mat\n\ndef porcelain_floor(width, depth):\n    \"\"\"Metre-scale ceramic slabs, with quiet surface variation and real joints.\"\"\"\n    grout=material('Warm grey fine grout',(.24,.23,.21),.82)\n    cube('Floor structural base',(width/2,depth/2,-.08),(width,depth,.12),grout)\n    finishes=[]\n    for index,offset in enumerate((-.012,-.006,0,.006,.012)):\n        mat=material(f'Matte limestone porcelain / tone {index}',(.38+offset,.365+offset,.335+offset),.47)\n        nodes,links=mat.node_tree.nodes,mat.node_tree.links\n        shader=nodes.get('Principled BSDF')\n        coord=nodes.new('ShaderNodeTexCoord')\n        cloud=nodes.new('ShaderNodeTexNoise')\n        cloud.inputs['Scale'].default_value=2.3\n        cloud.inputs['Detail'].default_value=2\n        cloud.inputs['Roughness'].default_value=.55\n        links.new(coord.outputs['Object'],cloud.inputs['Vector'])\n        ramp=nodes.new('ShaderNodeValToRGB')\n        ramp.color_ramp.elements[0].color=(.36+offset,.345+offset,.316+offset,1)\n        ramp.color_ramp.elements[1].color=(.40+offset,.385+offset,.354+offset,1)\n        links.new(cloud.outputs['Fac'],ramp.inputs[0])\n        links.new(ramp.outputs[0],shader.inputs['Base Color'])\n        fine=nodes.new('ShaderNodeTexNoise')\n        fine.inputs['Scale'].default_value=360\n        fine.inputs['Detail'].default_value=1\n        links.new(coord.outputs['Object'],fine.inputs['Vector'])\n        bump=nodes.new('ShaderNodeBump')\n        bump.inputs['Strength'].default_value=.10\n        bump.inputs['Distance'].default_value=.00005\n        links.new(fine.outputs['Fac'],bump.inputs['Height'])\n        links.new(bump.outputs[0],shader.inputs['Normal'])\n        finishes.append(mat)\n    size=1.2\n    gap=.002\n    for ix in range(math.ceil(width/size)):\n        for iy in range(math.ceil(depth/size)):\n            sx=min(size,width-ix*size)\n            sy=min(size,depth-iy*size)\n            tile=cube(f'Porcelain slab {ix:02d}-{iy:02d}',\n                (ix*size+sx/2,iy*size+sy/2,-.01),(sx-gap,sy-gap,.02),\n                finishes[(ix*7+iy*13)%len(finishes)],.0007)\n            # World-space texture coordinates avoid repeating a pattern per slab.\n            texture_origin=bpy.data.objects.get('Floor texture coordinates')\n            if texture_origin is None:\n                texture_origin=bpy.data.objects.new('Floor texture coordinates',None)\n                bpy.context.collection.objects.link(texture_origin)\n                for mat in finishes:\n                    mat.node_tree.nodes.get('Texture Coordinate').object=texture_origin\n\ndef build_window():\n    \"\"\"A recessed casement in a real wall opening; no emissive glass.\"\"\"\n    before=set(bpy.data.objects)\n    frame=material('Window / satin off-white aluminium',(.65,.67,.65),.3)\n    reveal=material('Window / plaster reveal',(.59,.61,.57),.8)\n    gasket=material('Window / EPDM seals',(.026,.031,.028),.72)\n    sill=material('Window / honed limestone sill',(.48,.465,.43),.43,.00015)\n    # Opening is y=2.8..4.2 and z=1.13..2.63, through a 20 cm wall.\n    for y in (2.8,4.2):\n        cube('Window plaster jamb',(-.10,y,1.88),(.2,.035,1.50),reveal,.002)\n    cube('Window plaster head',(-.10,3.5,2.63),(.2,1.4,.035),reveal,.002)\n    for y in (2.84,4.16):\n        cube('Window outer frame / jamb',(-.105,y,1.88),(.075,.065,1.43),frame,.004)\n    for z in (1.17,2.59):\n        cube('Window outer frame / rail',(-.105,3.5,z),(.075,1.38,.065),frame,.004)\n    cube('Window central mullion',(-.087,3.5,1.88),(.082,.055,1.40),frame,.003)\n    glass=material('Window / clear double glazing',(.97,.985,1.0),.012)\n    shader=glass.node_tree.nodes.get('Principled BSDF')\n    shader.inputs['Transmission Weight'].default_value=1\n    shader.inputs['IOR'].default_value=1.46\n    for yc in (3.17,3.83):\n        for y in (yc-.285,yc+.285):\n            cube('Casement rubber seal',(-.090,y,1.88),(.016,.012,1.31),gasket,.001)\n        for z in (1.23,2.53):\n            cube('Casement rubber seal',(-.090,yc,z),(.016,.58,.012),gasket,.001)\n        cube('Window glass / transparent pane',(-.115,yc,1.88),(.004,.57,1.29),glass)\n    cube('Stone sill / projecting eased edge',(.025,3.5,1.11),(.34,1.52,.045),sill,.005)\n    metal=material('Window / brushed nickel hardware',(.36,.38,.37),.24)\n    metal.node_tree.nodes.get('Principled BSDF').inputs['Metallic'].default_value=.8\n    cube('Window handle base',(-.032,3.55,1.81),(.022,.025,.06),metal,.004)\n    cube('Window handle lever',(-.009,3.55,1.77),(.024,.018,.10),metal,.006)\n    # Daylight enters from outside the aperture; the frame casts real shadows.\n    light=area('Overcast daylight through opening',(-2.0,3.3,4.2),(1.5,2.5,.3),650,1.4,(.88,.94,1))\n    light.data.shape='RECTANGLE'\n    light.data.size=1.25\n    light.data.size_y=1.25\n    light.visible_camera=False\n    light.visible_glossy=False\n    light.visible_transmission=False\n    for obj in set(bpy.data.objects)-before:\n        obj.location.y+=WINDOW_CENTER_Y-3.5\n\ndef build_room(scenario):\n    w,d,h = scenario['physics']['room_size']\n    plaster = material('Warm chalk plaster',(.59,.57,.51),.86,.0012)\n    plaster_side = material('Muted sage limewash',(.31,.39,.34),.9,.0012)\n    trim = material('Painted ivory joinery',(.72,.70,.64),.48,.0003)\n    dark = material('Charcoal metal',(.025,.03,.029),.38)\n    oak = material('Natural oak frame',(.22,.115,.055),.5,.0005)\n    add_oak_grain(oak)\n    paper = material('Uncoated art paper',(.69,.64,.52),.95)\n    terracotta = material('Clay pigment',(.33,.12,.065),.95)\n    # Extend the display floor past the camera-side cutaway to avoid exposed edges.\n    visual_w, visual_d=max(w,12),max(d,12)\n    if scenario['assets']['floor']=='matte_limestone_porcelain':\n        porcelain_floor(visual_w,visual_d)\n    else:\n        floor_mat=terrazzo_material() if scenario['assets']['floor']=='procedural_fine_terrazzo' else floor_material(ROOT/'assets'/'polyhaven'/'volleyball_corner_rebound'/scenario['assets']['floor'])\n        cube('Floor', (visual_w/2,visual_d/2,-.1),(visual_w,visual_d,.2),floor_mat)\n    # Partition the wall around the actual window opening, retaining the solid\n    # impact face elsewhere. The glazing closes the unchanged collision plane.\n    for name,center,size in (\n        ('Wall_X / corner side',(-.1,(WINDOW_CENTER_Y-.7)/2,(h+.07)/2),(.2,WINDOW_CENTER_Y-.7,h-.07)),\n        ('Wall_X / outer side',(-.1,(WINDOW_CENTER_Y+.7+d)/2,(h+.07)/2),(.2,d-WINDOW_CENTER_Y-.7,h-.07)),\n        ('Wall_X / below window',(-.1,WINDOW_CENTER_Y,.60),(.2,1.4,1.06)),\n        ('Wall_X / above window',(-.1,WINDOW_CENTER_Y,(2.63+h)/2),(.2,1.4,h-2.63))):\n        cube(name,center,size,plaster_side)\n    cube('Wall_Y / impact face y=0',(w/2,-.1,(h+.07)/2),(w,.2,h-.07),plaster)\n    cube('Far wall X / physical boundary',(w+.1,d/2,h/2),(.2,d,h),plaster_side)\n    cube('Far wall Y / physical boundary',(w/2,d+.1,h/2),(w,.2,h),plaster)\n    # Lit only by the sky and the daylight through the window (see\n    # exempt_slab_from_fills), so its albedo carries the whole tone: 0.73\n    # was tuned against a slab that the interior fills also brushed.\n    ceiling=material('Ceiling / soft white plaster',(.88,.868,.832),.9)\n    cube('Interior ceiling',(w/2,d/2,h+.08),(w,d,.16),ceiling)\n    # Flush skirting: faces match the physics planes exactly, no visual protrusion.\n    cube('Flush skirting X',(-.1,d/2,.035),(.2,d,.07),trim)\n    cube('Flush skirting Y',(w/2,-.1,.035),(w,.2,.07),trim)\n    import_wall_art(MODELS/scenario['assets']['paintings'])\n    import_air_conditioner(MODELS/scenario['assets']['air_conditioner'])\n    build_background(oak,trim,dark,terracotta,plaster_side)\n    build_spare_balls(MODELS/scenario['assets']['ball'])\n    # Outlet is on a part of the wall away from the ball trajectory.\n    cube('Outlet face',(.004,2.9,.36),(.008,.085,.085),trim,.003)\n    for yy in (2.88,2.92):\n        cube('Outlet socket',(.009,yy,.36),(.003,.007,.016),dark,.001)\n    build_window()\n    area('Soft room fill',(4.2,4.5,2.88),(2.4,2.4,.2),200,3.5,(1,.96,.9))\n    area('Ceiling bounce',(1.7,1.7,2.85),(1.2,1,.0),90,2.4,(1,.97,.92))\n    # A broad, fixed fill lifts the foreground boards and the camera-facing\n    # side of the ball throughout the trajectory, without tracking the ball.\n    area('Broad foreground and ball fill',(7.0,5.8,2.65),(3.2,3.2,.8),120,3.5,(1,.97,.93))\n    scene = bpy.context.scene\n    scene.world = bpy.data.worlds.new('Quiet ambient interior')\n    scene.world.use_nodes=True\n    nodes,links=scene.world.node_tree.nodes,scene.world.node_tree.links\n    environment=nodes.new('ShaderNodeTexEnvironment')\n    environment.image=bpy.data.images.load(str(ROOT/'assets'/'polyhaven'/'volleyball_corner_rebound'/'overcast_industrial_courtyard_4k.hdr'),check_existing=True)\n    coord=nodes.new('ShaderNodeTexCoord')\n    mapping=nodes.new('ShaderNodeMapping')\n    mapping.inputs['Rotation'].default_value[2]=math.radians(270)\n    links.new(coord.outputs['Generated'],mapping.inputs['Vector'])\n    links.new(mapping.outputs[0],environment.inputs['Vector'])\n    links.new(environment.outputs['Color'],nodes['Background'].inputs['Color'])\n    nodes['Background'].inputs['Strength'].default_value=1.1\n\ndef cylinder(name, center, radius, depth, mat):\n    bpy.ops.mesh.primitive_cylinder_add(vertices=48,radius=radius,depth=depth,location=center)\n    obj=bpy.context.object\n    obj.name=name\n    obj.data.materials.append(mat)\n    for face in obj.data.polygons:\n        face.use_smooth=True\n    bevel=obj.modifiers.new('Ceramic rounded rim','BEVEL')\n    bevel.width=.007\n    bevel.segments=3\n    obj.modifiers.new('Weighted normals','WEIGHTED_NORMAL')\n    return obj\n\ndef add_oak_grain(mat):\n    nodes,links=mat.node_tree.nodes,mat.node_tree.links\n    if nodes.get('Oak grain color'):\n        return\n    coord=nodes.new('ShaderNodeTexCoord')\n    scale=nodes.new('ShaderNodeVectorMath')\n    scale.operation='MULTIPLY'\n    scale.inputs[1].default_value=(1.5,65,6)\n    links.new(coord.outputs['Object'],scale.inputs[0])\n    noise=nodes.new('ShaderNodeTexNoise')\n    noise.inputs['Scale'].default_value=3.0\n    noise.inputs['Detail'].default_value=2\n    links.new(scale.outputs['Vector'],noise.inputs['Vector'])\n    ramp=nodes.new('ShaderNodeValToRGB')\n    ramp.name='Oak grain color'\n    ramp.color_ramp.elements[0].position=.15\n    ramp.color_ramp.elements[0].color=(.17,.083,.033,1)\n    ramp.color_ramp.elements[1].position=.85\n    ramp.color_ramp.elements[1].color=(.29,.16,.075,1)\n    links.new(noise.outputs['Fac'],ramp.inputs[0])\n    links.new(ramp.outputs['Color'],nodes.get('Principled BSDF').inputs['Base Color'])\n\ndef build_background(oak,trim,dark,clay,sage):\n    x,y,z=CABINET_CENTER\n    w,d,h=CABINET_SIZE\n    cube('Closed oak sideboard',CABINET_CENTER,CABINET_SIZE,oak,.009)\n    front=y+d/2\n    for xx in (x-w/4,x+w/4):\n        cube('Recessed cabinet door',(xx,front+.002,z),(.70,.005,h-.11),oak,.003)\n        cube('Slim cabinet handle',(xx+.23,front+.015,z+.13),(.016,.026,.09),dark,.004)\n    book_colors=((.12,.19,.24),(.53,.28,.16),(.59,.57,.45))\n    top=h\n    for i,color in enumerate(book_colors):\n        cover=material(f'Clothbound book {i}',color,.85,.0005)\n        bx=x-.36+(.025 if i==1 else 0)\n        bz=top+.02+i*.038\n        cube('Book paper block',(bx,y+.005,bz),(.31,.105,.029),trim,.002)\n        for delta in (-.017,.017):\n            cube('Book cloth cover',(bx,y+.005,bz+delta),(.33,.12,.005),cover,.002)\n    cylinder('Earthenware vase',(x+.38,y,h+.15),.095,.30,clay)\n    cylinder('Vase dark opening',(x+.38,y,h+.302),.058,.002,dark)\n    # The corner is left empty: no planter, no foliage, nothing to trip the ball.\n\ndef exempt_slab_from_fills():\n    \"\"\"Let the ceiling hear the daylight and the sky, but not the interior fills.\n\n    The three interior fills are 2.4-3.5 m disks hanging 0.12-0.35 m under the\n    slab and tilted 45-70 degrees, so the rim of every one of them pokes up\n    through it -- `cz + r * sqrt(1 - nz^2)` puts their top edges at 3.19, 4.13 and\n    4.28 m against a slab whose underside is at 3.00 m.  Every other surface is\n    lit by the disk's face and does not care.  The slab is lit only by the rim,\n    at grazing angles, which is what the blotch on the ceiling is: measured over\n    the slab, the interior fills alone give mean 51.8 with std 18.8, while the\n    sky and the window daylight alone give a flat 0.4.\n\n    Light linking states that directly instead of moving lights that everything\n    else depends on.  Called once the whole shot exists, because the receiver\n    collection has to hold every object that is not the slab.\n    \"\"\"\n    slab = bpy.data.objects.get('Interior ceiling')\n    if slab is None or not hasattr(slab, 'light_linking'):\n        return None\n    existing = bpy.data.collections.get('Lit by the interior fills')\n    if existing is not None:\n        return existing\n    receivers = bpy.data.collections.new('Lit by the interior fills')\n    bpy.context.scene.collection.children.link(receivers)\n    for obj in bpy.context.scene.objects:\n        if obj is not slab:\n            receivers.objects.link(obj)\n    for obj in bpy.context.scene.objects:\n        if obj.type == 'LIGHT' and 'Overcast' not in obj.name:\n            obj.light_linking.receiver_collection = receivers\n    return receivers\n\n\ndef build_spare_balls(path):\n    first=import_ball(path,SPARE_BALL_RADIUS)\n    first.name='Spare volleyball 1 / static'\n    for index,position in enumerate(SPARE_BALL_CENTERS):\n        body=first if index==0 else first.copy()\n        if index:\n            body.data=first.data.copy()\n            bpy.context.collection.objects.link(body)\n        body.name=f'Spare volleyball {index+1} / static'\n        body.animation_data_clear()\n        body.location=position\n        body.rotation_mode='XYZ'\n        body.rotation_euler=((.4,.9,.2),(1.2,.3,2.1))[index]\n\ndef import_wall_art(path):\n    from mathutils import Matrix\n    before=set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(path))\n    bpy.context.view_layer.update()\n    imported=[o for o in bpy.data.objects if o not in before]\n    candidates=sorted([o for o in imported if o.type=='MESH' and 'wall_picture' in o.name],key=lambda o:o.name)\n    if not candidates:\n        raise ValueError('No framed picture meshes in cafe_wall_pictures.glb')\n    chosen=sorted([o for o in candidates if o.name.startswith(PICTURE_MESH)],key=lambda o:o.name)\n    original=(chosen or candidates)[0]\n    rotation=Matrix.Rotation(math.pi/2,4,'Z')\n    for index,(x,z,height) in enumerate(((3.0,1.75,.90),)):\n        mesh=original.data.copy()\n        mesh.transform(rotation@original.matrix_world)\n        lo=Vector(tuple(min(v.co[i] for v in mesh.vertices) for i in range(3)))\n        hi=Vector(tuple(max(v.co[i] for v in mesh.vertices) for i in range(3)))\n        origin=Vector(((lo.x+hi.x)/2,lo.y,(lo.z+hi.z)/2))\n        scale=height/(hi.z-lo.z)\n        for vertex in mesh.vertices:\n            vertex.co=(vertex.co-origin)*scale+Vector((x,.006,z))\n        body=bpy.data.objects.new(f'Imported framed art {index+1} / {original.name}',mesh)\n        bpy.context.collection.objects.link(body)\n        for mat in mesh.materials:\n            if mat and mat.use_nodes:\n                for node in mat.node_tree.nodes:\n                    if node.type=='BSDF_PRINCIPLED':\n                        node.inputs['Emission Strength'].default_value=0\n    for obj in imported:\n        bpy.data.objects.remove(obj,do_unlink=True)\n\ndef import_air_conditioner(path):\n    from mathutils import Matrix\n    before=set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(path))\n    imported=[o for o in bpy.data.objects if o not in before]\n    meshes=[o for o in imported if o.type=='MESH']\n    if not meshes:\n        raise ValueError('Indoor unit asset contains no meshes')\n    bpy.ops.object.select_all(action='DESELECT')\n    for obj in meshes:\n        obj.animation_data_clear()\n        obj.select_set(True)\n    bpy.context.view_layer.objects.active=meshes[0]\n    if len(meshes)>1:\n        bpy.ops.object.join()\n    body=bpy.context.object\n    world=body.matrix_world.copy()\n    body.parent=None\n    body.matrix_world=world\n    for obj in imported:\n        if obj!=body and obj.name in bpy.data.objects:\n            bpy.data.objects.remove(obj,do_unlink=True)\n    bpy.ops.object.transform_apply(location=True,rotation=True,scale=True)\n    # The asset's back is its +Y face and the louvre panel faces -Y.  The wall it\n    # goes on is x=0 with the room on +X, so a quarter turn about Z (+Y -> -X)\n    # lays the back on the plaster and points the panel into the room; the unit's\n    # width then runs along Y and its depth along X, which is why AC_SIZE swaps\n    # the two.  Width, not height, is what a split is specified by, so that is\n    # the one dimension the uniform scale is pinned to.\n    body.data.transform(Matrix.Rotation(math.pi/2,4,'Z'))\n    lo=Vector(tuple(min(v.co[i] for v in body.data.vertices) for i in range(3)))\n    hi=Vector(tuple(max(v.co[i] for v in body.data.vertices) for i in range(3)))\n    factor=AC_WIDTH/(hi.y-lo.y)\n    centre=Vector((lo.x,(lo.y+hi.y)*.5,(lo.z+hi.z)*.5))\n    for vertex in body.data.vertices:\n        vertex.co=(vertex.co-centre)*factor+Vector((AC_BACK_GAP,AC_CENTER[1],AC_CENTER[2]))\n    body.location=(0,0,0)\n    body.name='Split indoor unit'\n    for poly in body.data.polygons:\n        poly.use_smooth=True\n    for mat in body.data.materials:\n        if not mat or not mat.use_nodes:\n            continue\n        for node in mat.node_tree.nodes:\n            if node.type=='BSDF_PRINCIPLED':\n                node.inputs['Emission Strength'].default_value=0\n                # The glb's packed metallic channel reads 0.91 over the painted\n                # shell, which is an authoring slip rather than the object: a\n                # split indoor unit is painted steel and plastic.  Under this\n                # overcast HDR that value turns it into a mirror and it renders\n                # blue-grey, so metallic is pinned to 0.  Roughness keeps the\n                # supplied map, so the sheen is still the asset's own.\n                for link in list(node.inputs['Metallic'].links):\n                    mat.node_tree.links.remove(link)\n                node.inputs['Metallic'].default_value=0\n\ndef import_ball(path, radius):\n    before=set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(path))\n    imported=[o for o in bpy.data.objects if o not in before]\n    meshes=[o for o in imported if o.type=='MESH']\n    if not meshes:\n        raise ValueError('Volleyball asset contains no meshes')\n    bpy.ops.object.select_all(action='DESELECT')\n    for obj in meshes:\n        obj.animation_data_clear()\n        obj.select_set(True)\n    bpy.context.view_layer.objects.active=meshes[0]\n    if len(meshes)>1:\n        bpy.ops.object.join()\n    ball=bpy.context.object\n    world=ball.matrix_world.copy()\n    ball.parent=None\n    ball.matrix_world=world\n    for obj in imported:\n        if obj!=ball and obj.name in bpy.data.objects:\n            bpy.data.objects.remove(obj,do_unlink=True)\n    bpy.ops.object.transform_apply(location=True,rotation=True,scale=True)\n    # Bounding sphere centre, so the visual centre matches GEOM_SPHERE.\n    lo=Vector(tuple(min(v.co[i] for v in ball.data.vertices) for i in range(3)))\n    hi=Vector(tuple(max(v.co[i] for v in ball.data.vertices) for i in range(3)))\n    center=(lo+hi)*.5\n    factor=2*radius/max(hi-lo)\n    for vertex in ball.data.vertices:\n        vertex.co=(vertex.co-center)*factor\n    ball.location=(0,0,0)\n    ball.name='volleyball'\n    for poly in ball.data.polygons:\n        poly.use_smooth=True\n    for mat in ball.data.materials:\n        if not mat or not mat.use_nodes:\n            continue\n        for node in mat.node_tree.nodes:\n            if node.type=='BSDF_PRINCIPLED':\n                node.inputs['Emission Strength'].default_value=0\n                if not node.inputs['Roughness'].is_linked:\n                    node.inputs['Roughness'].default_value=.68\n    return ball\n", "scene_support.volleyball_corner_rebound.scene_geometry": "\"\"\"Shared visual/physics dimensions of room furniture and static spare balls.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nCABINET_CENTER=(3.8,.11,.21)\nCABINET_SIZE=(1.5,.20,.42)\n# There is no plant in this room. The corner the ball rebounds into is the only\n# corner the camera can see, so a planter there would be a collider the two\n# low-restitution edits roll into; a planter anywhere else is either out of shot\n# or standing in front of the window. The corner is left empty instead, which is\n# also what the ball's own story needs: it comes to rest against the walls.\nSPARE_BALL_RADIUS=.105\n# Parked at the far end of the sideboard, clear of every run: at their old\n# spot the 1.5x speed edit passed a spare ball by 0.2 mm.\nSPARE_BALL_CENTERS=((4.75,.30,SPARE_BALL_RADIUS),(4.95,.80,SPARE_BALL_RADIUS))\nWINDOW_CENTER_Y=2.5\n# The split indoor unit hangs on the window wall, x=0, the wall the camera faces\n# most squarely: seen from the y=0 wall its face was foreshortened to 0.56 of its\n# length, here it keeps 0.95.  indoor_air_conditioner_unit imports as\n# 0.531 x 0.131 x 0.181 m; the room is 10 x 8 x 3 m = 240 m3, which a 3 HP wall\n# split of about 1.10 x 0.25 x 0.33 m serves, so the asset is scaled uniformly by\n# 2.26 to 1.20 m wide (0.409 high, 0.296 deep) and its own proportions are kept\n# rather than stretched to the figures.\nAC_SCALE=2.26\nAC_WIDTH=.531*AC_SCALE\nAC_DEPTH=.131*AC_SCALE\nAC_HEIGHT=.181*AC_SCALE\nAC_BACK_GAP=.006\n# Hung with its underside 2.40 m up and 0.90 m clear of the window's right reveal\n# at y=3.20, which puts the top of the case at 2.81 m: 0.19 m of clearance to the\n# 3.0 m ceiling, the gap the install manuals ask for and the reason the unit\n# cannot go higher.  Its own width runs along the wall (y) and its depth along x:\n# AC_SIZE is the axis-aligned box the simulator collides with, so width and depth\n# swap relative to the brief's W x D x H.\nAC_WALL_Y=4.70\nAC_BOTTOM_Z=2.40\nAC_CENTER=(AC_BACK_GAP+AC_DEPTH/2,AC_WALL_Y,AC_BOTTOM_Z+AC_HEIGHT/2)\nAC_SIZE=(AC_DEPTH,AC_WIDTH,AC_HEIGHT)\n\ndef geometry_snapshot():\n    return {'cabinet_center':list(CABINET_CENTER),'cabinet_size':list(CABINET_SIZE),\n        'spare_ball_radius':SPARE_BALL_RADIUS,'spare_ball_centers':[list(p) for p in SPARE_BALL_CENTERS],\n        'window_center_y':WINDOW_CENTER_Y,\n        'ac_center':list(AC_CENTER),'ac_size':list(AC_SIZE)}\n", "scene_support.volleyball_corner_rebound": "from pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n", "camera_rig": "\"\"\"Camera setup shared by every case; fixed mode has no camera animation.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport bpy\nimport math\nfrom mathutils import Vector\n\ndef animate_camera(camera, rows, config):\n    camera.animation_data_clear()\n    camera.data.animation_data_clear()\n    camera.location=config['camera_location']\n    camera.data.lens=config['lens_mm']\n    camera.rotation_mode='QUATERNION'\n    if config.get('camera_mode','fixed')=='fixed':\n        # Clear both object and lens actions so an older tracking setup cannot\n        # survive a switch to the locked camera, even in a saved Blender file.\n        focus=Vector(config['camera_target'])\n        rotation=(focus-camera.location).to_track_quat('-Z','Y')\n        camera.rotation_quaternion=rotation\n        return [{'frame_index':row['frame_index'],'location':list(camera.location),\n            'quaternion_xyzw':[rotation.x,rotation.y,rotation.z,rotation.w],\n            'focus':list(focus),'lens_mm':camera.data.lens} for row in rows]\n    alpha=float(config.get('tracking_smoothing',.65))\n    if not 0<alpha<=1:\n        raise ValueError('tracking_smoothing must be in (0,1]')\n    focus=None\n    poses=[]\n    previous=None\n    speed=math.hypot(*rows[0].get('ball_linear_velocity',[0,0,0]))\n    reference=float(config.get('tracking_speed_reference',5.85))\n    time_scale=min(1,reference/max(speed,.001))\n    for row in rows:\n        if config.get('camera_mode','fixed')=='tracking':\n            x,y,z=row['ball_location']\n            moving=Vector((x,y,max(.25,z-.15)))\n            hold=float(config.get('tracking_hold_sec',0))*time_scale\n            blend=max(.001,float(config.get('tracking_blend_sec',.45))*time_scale)\n            weight=max(0,min(1,(row['time_sec']-hold)/blend))\n            weight=weight*weight*(3-2*weight)\n            desired=Vector(config['camera_target']).lerp(moving,weight)\n            focus=desired if focus is None else focus.lerp(desired,alpha)\n        else:\n            focus=Vector(config['camera_target'])\n        rotation=(focus-camera.location).to_track_quat('-Z','Y')\n        if previous is not None and rotation.dot(previous)<0:\n            rotation.negate()\n        camera.rotation_quaternion=rotation\n        if config.get('adaptive_lens',False):\n            distance=(Vector(row['ball_location'])-camera.location).length\n            camera.data.lens=max(30,min(70,.055*36*distance/.21))\n            camera.data.keyframe_insert('lens',frame=row['frame_index'])\n        camera.keyframe_insert('rotation_quaternion',frame=row['frame_index'])\n        poses.append({'frame_index':row['frame_index'],'location':list(camera.location),\n            'quaternion_xyzw':[rotation.x,rotation.y,rotation.z,rotation.w],\n            'focus':list(focus),'lens_mm':camera.data.lens})\n        previous=rotation.copy()\n    for curve in camera.animation_data.action.fcurves:\n        for point in curve.keyframe_points:\n            point.interpolation='LINEAR'\n    if camera.data.animation_data:\n        for curve in camera.data.animation_data.action.fcurves:\n            for point in curve.keyframe_points:\n                point.interpolation='LINEAR'\n    return poses\n", "scene_config": "\"\"\"Single source of truth for simulation, edit vocabulary and visual geometry.\"\"\"\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport copy\nimport json\nimport math\nfrom pathlib import Path\n\nROOT = _PCVE_ROOT\nHERE = next((p for p in (ROOT / 'new-scripts' / 'volleyball_corner_rebound', ROOT / 'clean_scripts' / 'rigid_rigid' / 'volleyball_corner_rebound') if p.is_dir()), ROOT / 'clean_scripts' / 'rigid_rigid' / 'volleyball_corner_rebound')\nSCENARIO_DIR = ROOT / 'assets' / 'scenarios' / 'volleyball_corner_rebound'\nMODELS = ROOT / 'assets' / 'models'\n\n# Scene-control keys carry the in-run edit schedule rather than a measurement\n# of the room: they are absent from scenario.json, and every case has one\n# (empty unless the case carries a timed edit). Defaulting them before the\n# override patch is applied is what makes a schedule a legal physics override.\nSCENE_CONTROL_DEFAULTS = {'timed_edits': []}\n\ndef load_scenario(overrides=None):\n    result = json.loads((SCENARIO_DIR / 'scenario.json').read_text(encoding='utf-8'))\n    for key, value in SCENE_CONTROL_DEFAULTS.items():\n        result['physics'].setdefault(key, copy.deepcopy(value))\n    if overrides is not None:\n        patch = json.loads(Path(overrides).read_text(encoding='utf-8')) if isinstance(overrides, (str, Path)) else copy.deepcopy(overrides)\n        for section, values in patch.items():\n            if section not in result or not isinstance(values, dict):\n                raise ValueError(f'Unsupported scenario section: {section}')\n            unknown = set(values) - set(result[section])\n            if unknown:\n                raise ValueError(f'Unknown {section} keys: {sorted(unknown)}')\n            result[section].update(values)\n    p = result['physics']\n    for key in ('fps', 'duration_sec', 'substeps_per_frame', 'ball_mass', 'ball_radius', 'ball_initial_speed'):\n        if not math.isfinite(float(p[key])) or p[key] <= 0:\n            raise ValueError(f'{key} must be positive and finite')\n    for key in ('ball_restitution', 'floor_restitution', 'wall_restitution'):\n        if not 0 <= p[key] <= 1:\n            raise ValueError(f'{key} must be in [0, 1]')\n    for key in ('ball_friction', 'ball_rolling_friction', 'ball_spinning_friction', 'floor_friction', 'floor_rolling_friction', 'wall_friction', 'linear_damping', 'angular_damping'):\n        if not math.isfinite(float(p[key])) or p[key] < 0:\n            raise ValueError(f'{key} must be nonnegative and finite')\n    if len(p['room_size']) != 3 or min(p['room_size']) <= 0:\n        raise ValueError('room_size must contain three positive dimensions')\n    if len(p['launch_direction']) != 3 or not all(math.isfinite(v) for v in p['launch_direction']) or math.hypot(*p['launch_direction']) == 0:\n        raise ValueError('Nonzero finite launch_direction XYZ required')\n    if len(p['ball_initial_angular_velocity']) != 3 or not all(math.isfinite(v) for v in p['ball_initial_angular_velocity']):\n        raise ValueError('Finite initial angular velocity XYZ required')\n    if len(p['ball_initial_location']) != 3 or any(not math.isfinite(v) or not p['ball_radius'] < v < extent-p['ball_radius'] for v, extent in zip(p['ball_initial_location'], p['room_size'])):\n        raise ValueError('Ball starts outside the room or intersects a wall')\n    if 2*p['ball_radius'] >= p['room_size'][2]:\n        raise ValueError('Ball must fit below the ceiling')\n    return result\n\ndef write_json(path, value):\n    path = Path(path)\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(value, ensure_ascii=False, indent=2, allow_nan=False), encoding='utf-8')\n\ndef runtime(kind):\n    relative = 'render/Scripts/python.exe' if kind == 'render' else 'sim/python.exe'\n    for root in (ROOT, ROOT.parent / 'PCVE-ElasticBench'):\n        path = root / '.runtime' / relative\n        if path.is_file():\n            return str(path)\n    raise FileNotFoundError(f'No {kind} Python runtime; use an environment with bpy/pybullet')\n", "scene_environment": "\"\"\"Photographic materials and metre-scale architectural room, authored locally.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport math\nfrom pathlib import Path\nROOT = _PCVE_ROOT\nimport bpy\nfrom mathutils import Vector\nfrom scene_config import MODELS\nfrom scene_geometry import (AC_BACK_GAP, AC_CENTER, AC_HEIGHT, AC_WIDTH, CABINET_CENTER,\n    CABINET_SIZE, SPARE_BALL_CENTERS, SPARE_BALL_RADIUS, WINDOW_CENTER_Y)\n\n# cafe_wall_pictures.glb stacks three pictures on one shared 0.49 x 0.33 m mesh that\n# differ only in texture, so choosing the artwork is a name lookup: wall and frame\n# geometry stay put.  Picture 1 is a photo-real window-and-coffee-jar still life, its\n# dark frame and busy interior collapsing into a brown smudge at the size the far\n# camera gives it; picture 3 is a coffee-bean owl on cream that vanishes against the\n# pale wall; picture 2 is a copper mug on a flat blush ground and still reads as a\n# picture from across the room.\nPICTURE_MESH = 'wall_picture_2'\n\ndef material(name, color, roughness=.6, bump=.0):\n    mat = bpy.data.materials.new(name)\n    mat.diffuse_color = (*color, 1)\n    mat.use_nodes = True\n    nodes, links = mat.node_tree.nodes, mat.node_tree.links\n    bsdf = nodes.get('Principled BSDF')\n    bsdf.inputs['Base Color'].default_value = (*color, 1)\n    bsdf.inputs['Roughness'].default_value = roughness\n    if bump:\n        coord = nodes.new('ShaderNodeTexCoord')\n        noise = nodes.new('ShaderNodeTexNoise')\n        noise.inputs['Scale'].default_value = 170\n        noise.inputs['Detail'].default_value = 2\n        links.new(coord.outputs['Object'], noise.inputs['Vector'])\n        node = nodes.new('ShaderNodeBump')\n        node.inputs['Strength'].default_value = .22\n        node.inputs['Distance'].default_value = bump\n        links.new(noise.outputs['Fac'], node.inputs['Height'])\n        links.new(node.outputs['Normal'], bsdf.inputs['Normal'])\n    return mat\n\ndef cube(name, center, size, mat, bevel=0):\n    bpy.ops.mesh.primitive_cube_add(size=1, location=center)\n    obj = bpy.context.object\n    obj.name = name\n    obj.dimensions = size\n    bpy.ops.object.transform_apply(location=False, rotation=False, scale=True)\n    obj.data.materials.append(mat)\n    if bevel:\n        mod = obj.modifiers.new('Soft manufactured edges', 'BEVEL')\n        mod.width, mod.segments = bevel, 3\n        obj.modifiers.new('Weighted normals', 'WEIGHTED_NORMAL')\n    return obj\n\ndef aim(obj, point):\n    obj.rotation_euler = (Vector(point)-obj.location).to_track_quat('-Z','Y').to_euler()\n\ndef area(name, pos, target, power, size, color=(1,.89,.75)):\n    data = bpy.data.lights.new(name, 'AREA')\n    data.energy, data.shape, data.size, data.color = power, 'DISK', size, color\n    # These broad sources approximate bounced daylight, not visible fixtures.\n    # The HDR and room geometry provide the actual glass reflections.\n    data.specular_factor=0\n    obj = bpy.data.objects.new(name,data)\n    bpy.context.collection.objects.link(obj)\n    obj.location = pos\n    obj.visible_glossy=False\n    aim(obj,target)\n    return obj\n\ndef floor_material(path):\n    mat = material('Oak boards / scanned worn wood', (.32,.19,.09), .48)\n    nodes, links = mat.node_tree.nodes, mat.node_tree.links\n    bsdf = nodes.get('Principled BSDF')\n    uv = nodes.new('ShaderNodeTexCoord')\n    sep = nodes.new('ShaderNodeSeparateXYZ')\n    links.new(uv.outputs['Object'],sep.inputs[0])\n    combine = nodes.new('ShaderNodeCombineXYZ')\n    for axis in ('X','Y'):\n        scale = nodes.new('ShaderNodeMath')\n        scale.operation = 'MULTIPLY'\n        scale.inputs[1].default_value = .62\n        links.new(sep.outputs[axis],scale.inputs[0])\n        links.new(scale.outputs[0],combine.inputs[axis])\n    image = nodes.new('ShaderNodeTexImage')\n    image.image = bpy.data.images.load(str(path), check_existing=True)\n    image.extension = 'REPEAT'\n    links.new(combine.outputs[0],image.inputs['Vector'])\n    links.new(image.outputs['Color'],bsdf.inputs['Base Color'])\n    bump = nodes.new('ShaderNodeBump')\n    bump.inputs['Strength'].default_value = .18\n    bump.inputs['Distance'].default_value = .002\n    links.new(image.outputs['Color'],bump.inputs['Height'])\n    links.new(bump.outputs['Normal'],bsdf.inputs['Normal'])\n    return mat\n\ndef terrazzo_material():\n    mat=material('Fine warm-grey terrazzo / 1 m slabs',(.25,.265,.26),.49)\n    nodes,links=mat.node_tree.nodes,mat.node_tree.links\n    bsdf=nodes.get('Principled BSDF')\n    coord=nodes.new('ShaderNodeTexCoord')\n    chips=nodes.new('ShaderNodeTexVoronoi')\n    chips.inputs['Scale'].default_value=35\n    chips.distance='EUCLIDEAN'\n    links.new(coord.outputs['Object'],chips.inputs['Vector'])\n    gate=nodes.new('ShaderNodeMath')\n    gate.operation='LESS_THAN'\n    gate.inputs[1].default_value=.36\n    links.new(chips.outputs['Distance'],gate.inputs[0])\n    palette=nodes.new('ShaderNodeValToRGB')\n    palette.color_ramp.interpolation='CONSTANT'\n    for index,(position,color) in enumerate(((0,(.055,.065,.06,1)),(.35,(.24,.19,.14,1)),(.5,(.43,.45,.43,1)),(.7,(.62,.60,.54,1)))):\n        element=palette.color_ramp.elements[index] if index<2 else palette.color_ramp.elements.new(position)\n        element.position=position\n        element.color=color\n    links.new(chips.outputs['Color'],palette.inputs[0])\n    mix=nodes.new('ShaderNodeMixRGB')\n    mix.inputs[1].default_value=(.25,.265,.26,1)\n    links.new(gate.outputs[0],mix.inputs[0])\n    links.new(palette.outputs['Color'],mix.inputs[2])\n    separate=nodes.new('ShaderNodeSeparateXYZ')\n    links.new(coord.outputs['Object'],separate.inputs[0])\n    seams=[]\n    for axis in ('X','Y'):\n        fract=nodes.new('ShaderNodeMath')\n        fract.operation='FRACT'\n        links.new(separate.outputs[axis],fract.inputs[0])\n        seam=nodes.new('ShaderNodeMath')\n        seam.operation='LESS_THAN'\n        seam.inputs[1].default_value=.003\n        links.new(fract.outputs[0],seam.inputs[0])\n        seams.append(seam)\n    combine=nodes.new('ShaderNodeMath')\n    combine.operation='MAXIMUM'\n    for index,seam in enumerate(seams):\n        links.new(seam.outputs[0],combine.inputs[index])\n    grout=nodes.new('ShaderNodeMixRGB')\n    links.new(combine.outputs[0],grout.inputs[0])\n    links.new(mix.outputs[0],grout.inputs[1])\n    grout.inputs[2].default_value=(.11,.12,.11,1)\n    links.new(grout.outputs[0],bsdf.inputs['Base Color'])\n    grain=nodes.new('ShaderNodeTexNoise')\n    grain.inputs['Scale'].default_value=220\n    grain.inputs['Detail'].default_value=2\n    links.new(coord.outputs['Object'],grain.inputs['Vector'])\n    bump=nodes.new('ShaderNodeBump')\n    bump.inputs['Strength'].default_value=.13\n    bump.inputs['Distance'].default_value=.00022\n    links.new(grain.outputs['Fac'],bump.inputs['Height'])\n    links.new(bump.outputs['Normal'],bsdf.inputs['Normal'])\n    return mat\n\ndef porcelain_floor(width, depth):\n    \"\"\"Metre-scale ceramic slabs, with quiet surface variation and real joints.\"\"\"\n    grout=material('Warm grey fine grout',(.24,.23,.21),.82)\n    cube('Floor structural base',(width/2,depth/2,-.08),(width,depth,.12),grout)\n    finishes=[]\n    for index,offset in enumerate((-.012,-.006,0,.006,.012)):\n        mat=material(f'Matte limestone porcelain / tone {index}',(.38+offset,.365+offset,.335+offset),.47)\n        nodes,links=mat.node_tree.nodes,mat.node_tree.links\n        shader=nodes.get('Principled BSDF')\n        coord=nodes.new('ShaderNodeTexCoord')\n        cloud=nodes.new('ShaderNodeTexNoise')\n        cloud.inputs['Scale'].default_value=2.3\n        cloud.inputs['Detail'].default_value=2\n        cloud.inputs['Roughness'].default_value=.55\n        links.new(coord.outputs['Object'],cloud.inputs['Vector'])\n        ramp=nodes.new('ShaderNodeValToRGB')\n        ramp.color_ramp.elements[0].color=(.36+offset,.345+offset,.316+offset,1)\n        ramp.color_ramp.elements[1].color=(.40+offset,.385+offset,.354+offset,1)\n        links.new(cloud.outputs['Fac'],ramp.inputs[0])\n        links.new(ramp.outputs[0],shader.inputs['Base Color'])\n        fine=nodes.new('ShaderNodeTexNoise')\n        fine.inputs['Scale'].default_value=360\n        fine.inputs['Detail'].default_value=1\n        links.new(coord.outputs['Object'],fine.inputs['Vector'])\n        bump=nodes.new('ShaderNodeBump')\n        bump.inputs['Strength'].default_value=.10\n        bump.inputs['Distance'].default_value=.00005\n        links.new(fine.outputs['Fac'],bump.inputs['Height'])\n        links.new(bump.outputs[0],shader.inputs['Normal'])\n        finishes.append(mat)\n    size=1.2\n    gap=.002\n    for ix in range(math.ceil(width/size)):\n        for iy in range(math.ceil(depth/size)):\n            sx=min(size,width-ix*size)\n            sy=min(size,depth-iy*size)\n            tile=cube(f'Porcelain slab {ix:02d}-{iy:02d}',\n                (ix*size+sx/2,iy*size+sy/2,-.01),(sx-gap,sy-gap,.02),\n                finishes[(ix*7+iy*13)%len(finishes)],.0007)\n            # World-space texture coordinates avoid repeating a pattern per slab.\n            texture_origin=bpy.data.objects.get('Floor texture coordinates')\n            if texture_origin is None:\n                texture_origin=bpy.data.objects.new('Floor texture coordinates',None)\n                bpy.context.collection.objects.link(texture_origin)\n                for mat in finishes:\n                    mat.node_tree.nodes.get('Texture Coordinate').object=texture_origin\n\ndef build_window():\n    \"\"\"A recessed casement in a real wall opening; no emissive glass.\"\"\"\n    before=set(bpy.data.objects)\n    frame=material('Window / satin off-white aluminium',(.65,.67,.65),.3)\n    reveal=material('Window / plaster reveal',(.59,.61,.57),.8)\n    gasket=material('Window / EPDM seals',(.026,.031,.028),.72)\n    sill=material('Window / honed limestone sill',(.48,.465,.43),.43,.00015)\n    # Opening is y=2.8..4.2 and z=1.13..2.63, through a 20 cm wall.\n    for y in (2.8,4.2):\n        cube('Window plaster jamb',(-.10,y,1.88),(.2,.035,1.50),reveal,.002)\n    cube('Window plaster head',(-.10,3.5,2.63),(.2,1.4,.035),reveal,.002)\n    for y in (2.84,4.16):\n        cube('Window outer frame / jamb',(-.105,y,1.88),(.075,.065,1.43),frame,.004)\n    for z in (1.17,2.59):\n        cube('Window outer frame / rail',(-.105,3.5,z),(.075,1.38,.065),frame,.004)\n    cube('Window central mullion',(-.087,3.5,1.88),(.082,.055,1.40),frame,.003)\n    glass=material('Window / clear double glazing',(.97,.985,1.0),.012)\n    shader=glass.node_tree.nodes.get('Principled BSDF')\n    shader.inputs['Transmission Weight'].default_value=1\n    shader.inputs['IOR'].default_value=1.46\n    for yc in (3.17,3.83):\n        for y in (yc-.285,yc+.285):\n            cube('Casement rubber seal',(-.090,y,1.88),(.016,.012,1.31),gasket,.001)\n        for z in (1.23,2.53):\n            cube('Casement rubber seal',(-.090,yc,z),(.016,.58,.012),gasket,.001)\n        cube('Window glass / transparent pane',(-.115,yc,1.88),(.004,.57,1.29),glass)\n    cube('Stone sill / projecting eased edge',(.025,3.5,1.11),(.34,1.52,.045),sill,.005)\n    metal=material('Window / brushed nickel hardware',(.36,.38,.37),.24)\n    metal.node_tree.nodes.get('Principled BSDF').inputs['Metallic'].default_value=.8\n    cube('Window handle base',(-.032,3.55,1.81),(.022,.025,.06),metal,.004)\n    cube('Window handle lever',(-.009,3.55,1.77),(.024,.018,.10),metal,.006)\n    # Daylight enters from outside the aperture; the frame casts real shadows.\n    light=area('Overcast daylight through opening',(-2.0,3.3,4.2),(1.5,2.5,.3),650,1.4,(.88,.94,1))\n    light.data.shape='RECTANGLE'\n    light.data.size=1.25\n    light.data.size_y=1.25\n    light.visible_camera=False\n    light.visible_glossy=False\n    light.visible_transmission=False\n    for obj in set(bpy.data.objects)-before:\n        obj.location.y+=WINDOW_CENTER_Y-3.5\n\ndef build_room(scenario):\n    w,d,h = scenario['physics']['room_size']\n    plaster = material('Warm chalk plaster',(.59,.57,.51),.86,.0012)\n    plaster_side = material('Muted sage limewash',(.31,.39,.34),.9,.0012)\n    trim = material('Painted ivory joinery',(.72,.70,.64),.48,.0003)\n    dark = material('Charcoal metal',(.025,.03,.029),.38)\n    oak = material('Natural oak frame',(.22,.115,.055),.5,.0005)\n    add_oak_grain(oak)\n    paper = material('Uncoated art paper',(.69,.64,.52),.95)\n    terracotta = material('Clay pigment',(.33,.12,.065),.95)\n    # Extend the display floor past the camera-side cutaway to avoid exposed edges.\n    visual_w, visual_d=max(w,12),max(d,12)\n    if scenario['assets']['floor']=='matte_limestone_porcelain':\n        porcelain_floor(visual_w,visual_d)\n    else:\n        floor_mat=terrazzo_material() if scenario['assets']['floor']=='procedural_fine_terrazzo' else floor_material(ROOT/'assets'/'polyhaven'/'volleyball_corner_rebound'/scenario['assets']['floor'])\n        cube('Floor', (visual_w/2,visual_d/2,-.1),(visual_w,visual_d,.2),floor_mat)\n    # Partition the wall around the actual window opening, retaining the solid\n    # impact face elsewhere. The glazing closes the unchanged collision plane.\n    for name,center,size in (\n        ('Wall_X / corner side',(-.1,(WINDOW_CENTER_Y-.7)/2,(h+.07)/2),(.2,WINDOW_CENTER_Y-.7,h-.07)),\n        ('Wall_X / outer side',(-.1,(WINDOW_CENTER_Y+.7+d)/2,(h+.07)/2),(.2,d-WINDOW_CENTER_Y-.7,h-.07)),\n        ('Wall_X / below window',(-.1,WINDOW_CENTER_Y,.60),(.2,1.4,1.06)),\n        ('Wall_X / above window',(-.1,WINDOW_CENTER_Y,(2.63+h)/2),(.2,1.4,h-2.63))):\n        cube(name,center,size,plaster_side)\n    cube('Wall_Y / impact face y=0',(w/2,-.1,(h+.07)/2),(w,.2,h-.07),plaster)\n    cube('Far wall X / physical boundary',(w+.1,d/2,h/2),(.2,d,h),plaster_side)\n    cube('Far wall Y / physical boundary',(w/2,d+.1,h/2),(w,.2,h),plaster)\n    # Lit only by the sky and the daylight through the window (see\n    # exempt_slab_from_fills), so its albedo carries the whole tone: 0.73\n    # was tuned against a slab that the interior fills also brushed.\n    ceiling=material('Ceiling / soft white plaster',(.88,.868,.832),.9)\n    cube('Interior ceiling',(w/2,d/2,h+.08),(w,d,.16),ceiling)\n    # Flush skirting: faces match the physics planes exactly, no visual protrusion.\n    cube('Flush skirting X',(-.1,d/2,.035),(.2,d,.07),trim)\n    cube('Flush skirting Y',(w/2,-.1,.035),(w,.2,.07),trim)\n    import_wall_art(MODELS/scenario['assets']['paintings'])\n    import_air_conditioner(MODELS/scenario['assets']['air_conditioner'])\n    build_background(oak,trim,dark,terracotta,plaster_side)\n    build_spare_balls(MODELS/scenario['assets']['ball'])\n    # Outlet is on a part of the wall away from the ball trajectory.\n    cube('Outlet face',(.004,2.9,.36),(.008,.085,.085),trim,.003)\n    for yy in (2.88,2.92):\n        cube('Outlet socket',(.009,yy,.36),(.003,.007,.016),dark,.001)\n    build_window()\n    area('Soft room fill',(4.2,4.5,2.88),(2.4,2.4,.2),200,3.5,(1,.96,.9))\n    area('Ceiling bounce',(1.7,1.7,2.85),(1.2,1,.0),90,2.4,(1,.97,.92))\n    # A broad, fixed fill lifts the foreground boards and the camera-facing\n    # side of the ball throughout the trajectory, without tracking the ball.\n    area('Broad foreground and ball fill',(7.0,5.8,2.65),(3.2,3.2,.8),120,3.5,(1,.97,.93))\n    scene = bpy.context.scene\n    scene.world = bpy.data.worlds.new('Quiet ambient interior')\n    scene.world.use_nodes=True\n    nodes,links=scene.world.node_tree.nodes,scene.world.node_tree.links\n    environment=nodes.new('ShaderNodeTexEnvironment')\n    environment.image=bpy.data.images.load(str(ROOT/'assets'/'polyhaven'/'volleyball_corner_rebound'/'overcast_industrial_courtyard_4k.hdr'),check_existing=True)\n    coord=nodes.new('ShaderNodeTexCoord')\n    mapping=nodes.new('ShaderNodeMapping')\n    mapping.inputs['Rotation'].default_value[2]=math.radians(270)\n    links.new(coord.outputs['Generated'],mapping.inputs['Vector'])\n    links.new(mapping.outputs[0],environment.inputs['Vector'])\n    links.new(environment.outputs['Color'],nodes['Background'].inputs['Color'])\n    nodes['Background'].inputs['Strength'].default_value=1.1\n\ndef cylinder(name, center, radius, depth, mat):\n    bpy.ops.mesh.primitive_cylinder_add(vertices=48,radius=radius,depth=depth,location=center)\n    obj=bpy.context.object\n    obj.name=name\n    obj.data.materials.append(mat)\n    for face in obj.data.polygons:\n        face.use_smooth=True\n    bevel=obj.modifiers.new('Ceramic rounded rim','BEVEL')\n    bevel.width=.007\n    bevel.segments=3\n    obj.modifiers.new('Weighted normals','WEIGHTED_NORMAL')\n    return obj\n\ndef add_oak_grain(mat):\n    nodes,links=mat.node_tree.nodes,mat.node_tree.links\n    if nodes.get('Oak grain color'):\n        return\n    coord=nodes.new('ShaderNodeTexCoord')\n    scale=nodes.new('ShaderNodeVectorMath')\n    scale.operation='MULTIPLY'\n    scale.inputs[1].default_value=(1.5,65,6)\n    links.new(coord.outputs['Object'],scale.inputs[0])\n    noise=nodes.new('ShaderNodeTexNoise')\n    noise.inputs['Scale'].default_value=3.0\n    noise.inputs['Detail'].default_value=2\n    links.new(scale.outputs['Vector'],noise.inputs['Vector'])\n    ramp=nodes.new('ShaderNodeValToRGB')\n    ramp.name='Oak grain color'\n    ramp.color_ramp.elements[0].position=.15\n    ramp.color_ramp.elements[0].color=(.17,.083,.033,1)\n    ramp.color_ramp.elements[1].position=.85\n    ramp.color_ramp.elements[1].color=(.29,.16,.075,1)\n    links.new(noise.outputs['Fac'],ramp.inputs[0])\n    links.new(ramp.outputs['Color'],nodes.get('Principled BSDF').inputs['Base Color'])\n\ndef build_background(oak,trim,dark,clay,sage):\n    x,y,z=CABINET_CENTER\n    w,d,h=CABINET_SIZE\n    cube('Closed oak sideboard',CABINET_CENTER,CABINET_SIZE,oak,.009)\n    front=y+d/2\n    for xx in (x-w/4,x+w/4):\n        cube('Recessed cabinet door',(xx,front+.002,z),(.70,.005,h-.11),oak,.003)\n        cube('Slim cabinet handle',(xx+.23,front+.015,z+.13),(.016,.026,.09),dark,.004)\n    book_colors=((.12,.19,.24),(.53,.28,.16),(.59,.57,.45))\n    top=h\n    for i,color in enumerate(book_colors):\n        cover=material(f'Clothbound book {i}',color,.85,.0005)\n        bx=x-.36+(.025 if i==1 else 0)\n        bz=top+.02+i*.038\n        cube('Book paper block',(bx,y+.005,bz),(.31,.105,.029),trim,.002)\n        for delta in (-.017,.017):\n            cube('Book cloth cover',(bx,y+.005,bz+delta),(.33,.12,.005),cover,.002)\n    cylinder('Earthenware vase',(x+.38,y,h+.15),.095,.30,clay)\n    cylinder('Vase dark opening',(x+.38,y,h+.302),.058,.002,dark)\n    # The corner is left empty: no planter, no foliage, nothing to trip the ball.\n\ndef exempt_slab_from_fills():\n    \"\"\"Let the ceiling hear the daylight and the sky, but not the interior fills.\n\n    The three interior fills are 2.4-3.5 m disks hanging 0.12-0.35 m under the\n    slab and tilted 45-70 degrees, so the rim of every one of them pokes up\n    through it -- `cz + r * sqrt(1 - nz^2)` puts their top edges at 3.19, 4.13 and\n    4.28 m against a slab whose underside is at 3.00 m.  Every other surface is\n    lit by the disk's face and does not care.  The slab is lit only by the rim,\n    at grazing angles, which is what the blotch on the ceiling is: measured over\n    the slab, the interior fills alone give mean 51.8 with std 18.8, while the\n    sky and the window daylight alone give a flat 0.4.\n\n    Light linking states that directly instead of moving lights that everything\n    else depends on.  Called once the whole shot exists, because the receiver\n    collection has to hold every object that is not the slab.\n    \"\"\"\n    slab = bpy.data.objects.get('Interior ceiling')\n    if slab is None or not hasattr(slab, 'light_linking'):\n        return None\n    existing = bpy.data.collections.get('Lit by the interior fills')\n    if existing is not None:\n        return existing\n    receivers = bpy.data.collections.new('Lit by the interior fills')\n    bpy.context.scene.collection.children.link(receivers)\n    for obj in bpy.context.scene.objects:\n        if obj is not slab:\n            receivers.objects.link(obj)\n    for obj in bpy.context.scene.objects:\n        if obj.type == 'LIGHT' and 'Overcast' not in obj.name:\n            obj.light_linking.receiver_collection = receivers\n    return receivers\n\n\ndef build_spare_balls(path):\n    first=import_ball(path,SPARE_BALL_RADIUS)\n    first.name='Spare volleyball 1 / static'\n    for index,position in enumerate(SPARE_BALL_CENTERS):\n        body=first if index==0 else first.copy()\n        if index:\n            body.data=first.data.copy()\n            bpy.context.collection.objects.link(body)\n        body.name=f'Spare volleyball {index+1} / static'\n        body.animation_data_clear()\n        body.location=position\n        body.rotation_mode='XYZ'\n        body.rotation_euler=((.4,.9,.2),(1.2,.3,2.1))[index]\n\ndef import_wall_art(path):\n    from mathutils import Matrix\n    before=set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(path))\n    bpy.context.view_layer.update()\n    imported=[o for o in bpy.data.objects if o not in before]\n    candidates=sorted([o for o in imported if o.type=='MESH' and 'wall_picture' in o.name],key=lambda o:o.name)\n    if not candidates:\n        raise ValueError('No framed picture meshes in cafe_wall_pictures.glb')\n    chosen=sorted([o for o in candidates if o.name.startswith(PICTURE_MESH)],key=lambda o:o.name)\n    original=(chosen or candidates)[0]\n    rotation=Matrix.Rotation(math.pi/2,4,'Z')\n    for index,(x,z,height) in enumerate(((3.0,1.75,.90),)):\n        mesh=original.data.copy()\n        mesh.transform(rotation@original.matrix_world)\n        lo=Vector(tuple(min(v.co[i] for v in mesh.vertices) for i in range(3)))\n        hi=Vector(tuple(max(v.co[i] for v in mesh.vertices) for i in range(3)))\n        origin=Vector(((lo.x+hi.x)/2,lo.y,(lo.z+hi.z)/2))\n        scale=height/(hi.z-lo.z)\n        for vertex in mesh.vertices:\n            vertex.co=(vertex.co-origin)*scale+Vector((x,.006,z))\n        body=bpy.data.objects.new(f'Imported framed art {index+1} / {original.name}',mesh)\n        bpy.context.collection.objects.link(body)\n        for mat in mesh.materials:\n            if mat and mat.use_nodes:\n                for node in mat.node_tree.nodes:\n                    if node.type=='BSDF_PRINCIPLED':\n                        node.inputs['Emission Strength'].default_value=0\n    for obj in imported:\n        bpy.data.objects.remove(obj,do_unlink=True)\n\ndef import_air_conditioner(path):\n    from mathutils import Matrix\n    before=set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(path))\n    imported=[o for o in bpy.data.objects if o not in before]\n    meshes=[o for o in imported if o.type=='MESH']\n    if not meshes:\n        raise ValueError('Indoor unit asset contains no meshes')\n    bpy.ops.object.select_all(action='DESELECT')\n    for obj in meshes:\n        obj.animation_data_clear()\n        obj.select_set(True)\n    bpy.context.view_layer.objects.active=meshes[0]\n    if len(meshes)>1:\n        bpy.ops.object.join()\n    body=bpy.context.object\n    world=body.matrix_world.copy()\n    body.parent=None\n    body.matrix_world=world\n    for obj in imported:\n        if obj!=body and obj.name in bpy.data.objects:\n            bpy.data.objects.remove(obj,do_unlink=True)\n    bpy.ops.object.transform_apply(location=True,rotation=True,scale=True)\n    # The asset's back is its +Y face and the louvre panel faces -Y.  The wall it\n    # goes on is x=0 with the room on +X, so a quarter turn about Z (+Y -> -X)\n    # lays the back on the plaster and points the panel into the room; the unit's\n    # width then runs along Y and its depth along X, which is why AC_SIZE swaps\n    # the two.  Width, not height, is what a split is specified by, so that is\n    # the one dimension the uniform scale is pinned to.\n    body.data.transform(Matrix.Rotation(math.pi/2,4,'Z'))\n    lo=Vector(tuple(min(v.co[i] for v in body.data.vertices) for i in range(3)))\n    hi=Vector(tuple(max(v.co[i] for v in body.data.vertices) for i in range(3)))\n    factor=AC_WIDTH/(hi.y-lo.y)\n    centre=Vector((lo.x,(lo.y+hi.y)*.5,(lo.z+hi.z)*.5))\n    for vertex in body.data.vertices:\n        vertex.co=(vertex.co-centre)*factor+Vector((AC_BACK_GAP,AC_CENTER[1],AC_CENTER[2]))\n    body.location=(0,0,0)\n    body.name='Split indoor unit'\n    for poly in body.data.polygons:\n        poly.use_smooth=True\n    for mat in body.data.materials:\n        if not mat or not mat.use_nodes:\n            continue\n        for node in mat.node_tree.nodes:\n            if node.type=='BSDF_PRINCIPLED':\n                node.inputs['Emission Strength'].default_value=0\n                # The glb's packed metallic channel reads 0.91 over the painted\n                # shell, which is an authoring slip rather than the object: a\n                # split indoor unit is painted steel and plastic.  Under this\n                # overcast HDR that value turns it into a mirror and it renders\n                # blue-grey, so metallic is pinned to 0.  Roughness keeps the\n                # supplied map, so the sheen is still the asset's own.\n                for link in list(node.inputs['Metallic'].links):\n                    mat.node_tree.links.remove(link)\n                node.inputs['Metallic'].default_value=0\n\ndef import_ball(path, radius):\n    before=set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(path))\n    imported=[o for o in bpy.data.objects if o not in before]\n    meshes=[o for o in imported if o.type=='MESH']\n    if not meshes:\n        raise ValueError('Volleyball asset contains no meshes')\n    bpy.ops.object.select_all(action='DESELECT')\n    for obj in meshes:\n        obj.animation_data_clear()\n        obj.select_set(True)\n    bpy.context.view_layer.objects.active=meshes[0]\n    if len(meshes)>1:\n        bpy.ops.object.join()\n    ball=bpy.context.object\n    world=ball.matrix_world.copy()\n    ball.parent=None\n    ball.matrix_world=world\n    for obj in imported:\n        if obj!=ball and obj.name in bpy.data.objects:\n            bpy.data.objects.remove(obj,do_unlink=True)\n    bpy.ops.object.transform_apply(location=True,rotation=True,scale=True)\n    # Bounding sphere centre, so the visual centre matches GEOM_SPHERE.\n    lo=Vector(tuple(min(v.co[i] for v in ball.data.vertices) for i in range(3)))\n    hi=Vector(tuple(max(v.co[i] for v in ball.data.vertices) for i in range(3)))\n    center=(lo+hi)*.5\n    factor=2*radius/max(hi-lo)\n    for vertex in ball.data.vertices:\n        vertex.co=(vertex.co-center)*factor\n    ball.location=(0,0,0)\n    ball.name='volleyball'\n    for poly in ball.data.polygons:\n        poly.use_smooth=True\n    for mat in ball.data.materials:\n        if not mat or not mat.use_nodes:\n            continue\n        for node in mat.node_tree.nodes:\n            if node.type=='BSDF_PRINCIPLED':\n                node.inputs['Emission Strength'].default_value=0\n                if not node.inputs['Roughness'].is_linked:\n                    node.inputs['Roughness'].default_value=.68\n    return ball\n", "scene_geometry": "\"\"\"Shared visual/physics dimensions of room furniture and static spare balls.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nCABINET_CENTER=(3.8,.11,.21)\nCABINET_SIZE=(1.5,.20,.42)\n# There is no plant in this room. The corner the ball rebounds into is the only\n# corner the camera can see, so a planter there would be a collider the two\n# low-restitution edits roll into; a planter anywhere else is either out of shot\n# or standing in front of the window. The corner is left empty instead, which is\n# also what the ball's own story needs: it comes to rest against the walls.\nSPARE_BALL_RADIUS=.105\n# Parked at the far end of the sideboard, clear of every run: at their old\n# spot the 1.5x speed edit passed a spare ball by 0.2 mm.\nSPARE_BALL_CENTERS=((4.75,.30,SPARE_BALL_RADIUS),(4.95,.80,SPARE_BALL_RADIUS))\nWINDOW_CENTER_Y=2.5\n# The split indoor unit hangs on the window wall, x=0, the wall the camera faces\n# most squarely: seen from the y=0 wall its face was foreshortened to 0.56 of its\n# length, here it keeps 0.95.  indoor_air_conditioner_unit imports as\n# 0.531 x 0.131 x 0.181 m; the room is 10 x 8 x 3 m = 240 m3, which a 3 HP wall\n# split of about 1.10 x 0.25 x 0.33 m serves, so the asset is scaled uniformly by\n# 2.26 to 1.20 m wide (0.409 high, 0.296 deep) and its own proportions are kept\n# rather than stretched to the figures.\nAC_SCALE=2.26\nAC_WIDTH=.531*AC_SCALE\nAC_DEPTH=.131*AC_SCALE\nAC_HEIGHT=.181*AC_SCALE\nAC_BACK_GAP=.006\n# Hung with its underside 2.40 m up and 0.90 m clear of the window's right reveal\n# at y=3.20, which puts the top of the case at 2.81 m: 0.19 m of clearance to the\n# 3.0 m ceiling, the gap the install manuals ask for and the reason the unit\n# cannot go higher.  Its own width runs along the wall (y) and its depth along x:\n# AC_SIZE is the axis-aligned box the simulator collides with, so width and depth\n# swap relative to the brief's W x D x H.\nAC_WALL_Y=4.70\nAC_BOTTOM_Z=2.40\nAC_CENTER=(AC_BACK_GAP+AC_DEPTH/2,AC_WALL_Y,AC_BOTTOM_Z+AC_HEIGHT/2)\nAC_SIZE=(AC_DEPTH,AC_WIDTH,AC_HEIGHT)\n\ndef geometry_snapshot():\n    return {'cabinet_center':list(CABINET_CENTER),'cabinet_size':list(CABINET_SIZE),\n        'spare_ball_radius':SPARE_BALL_RADIUS,'spare_ball_centers':[list(p) for p in SPARE_BALL_CENTERS],\n        'window_center_y':WINDOW_CENTER_Y,\n        'ac_center':list(AC_CENTER),'ac_size':list(AC_SIZE)}\n", "volleyball_corner_rebound.camera_rig": "\"\"\"Camera setup shared by every case; fixed mode has no camera animation.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport bpy\nimport math\nfrom mathutils import Vector\n\ndef animate_camera(camera, rows, config):\n    camera.animation_data_clear()\n    camera.data.animation_data_clear()\n    camera.location=config['camera_location']\n    camera.data.lens=config['lens_mm']\n    camera.rotation_mode='QUATERNION'\n    if config.get('camera_mode','fixed')=='fixed':\n        # Clear both object and lens actions so an older tracking setup cannot\n        # survive a switch to the locked camera, even in a saved Blender file.\n        focus=Vector(config['camera_target'])\n        rotation=(focus-camera.location).to_track_quat('-Z','Y')\n        camera.rotation_quaternion=rotation\n        return [{'frame_index':row['frame_index'],'location':list(camera.location),\n            'quaternion_xyzw':[rotation.x,rotation.y,rotation.z,rotation.w],\n            'focus':list(focus),'lens_mm':camera.data.lens} for row in rows]\n    alpha=float(config.get('tracking_smoothing',.65))\n    if not 0<alpha<=1:\n        raise ValueError('tracking_smoothing must be in (0,1]')\n    focus=None\n    poses=[]\n    previous=None\n    speed=math.hypot(*rows[0].get('ball_linear_velocity',[0,0,0]))\n    reference=float(config.get('tracking_speed_reference',5.85))\n    time_scale=min(1,reference/max(speed,.001))\n    for row in rows:\n        if config.get('camera_mode','fixed')=='tracking':\n            x,y,z=row['ball_location']\n            moving=Vector((x,y,max(.25,z-.15)))\n            hold=float(config.get('tracking_hold_sec',0))*time_scale\n            blend=max(.001,float(config.get('tracking_blend_sec',.45))*time_scale)\n            weight=max(0,min(1,(row['time_sec']-hold)/blend))\n            weight=weight*weight*(3-2*weight)\n            desired=Vector(config['camera_target']).lerp(moving,weight)\n            focus=desired if focus is None else focus.lerp(desired,alpha)\n        else:\n            focus=Vector(config['camera_target'])\n        rotation=(focus-camera.location).to_track_quat('-Z','Y')\n        if previous is not None and rotation.dot(previous)<0:\n            rotation.negate()\n        camera.rotation_quaternion=rotation\n        if config.get('adaptive_lens',False):\n            distance=(Vector(row['ball_location'])-camera.location).length\n            camera.data.lens=max(30,min(70,.055*36*distance/.21))\n            camera.data.keyframe_insert('lens',frame=row['frame_index'])\n        camera.keyframe_insert('rotation_quaternion',frame=row['frame_index'])\n        poses.append({'frame_index':row['frame_index'],'location':list(camera.location),\n            'quaternion_xyzw':[rotation.x,rotation.y,rotation.z,rotation.w],\n            'focus':list(focus),'lens_mm':camera.data.lens})\n        previous=rotation.copy()\n    for curve in camera.animation_data.action.fcurves:\n        for point in curve.keyframe_points:\n            point.interpolation='LINEAR'\n    if camera.data.animation_data:\n        for curve in camera.data.animation_data.action.fcurves:\n            for point in curve.keyframe_points:\n                point.interpolation='LINEAR'\n    return poses\n", "volleyball_corner_rebound.scene_config": "\"\"\"Single source of truth for simulation, edit vocabulary and visual geometry.\"\"\"\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport copy\nimport json\nimport math\nfrom pathlib import Path\n\nROOT = _PCVE_ROOT\nHERE = next((p for p in (ROOT / 'new-scripts' / 'volleyball_corner_rebound', ROOT / 'clean_scripts' / 'rigid_rigid' / 'volleyball_corner_rebound') if p.is_dir()), ROOT / 'clean_scripts' / 'rigid_rigid' / 'volleyball_corner_rebound')\nSCENARIO_DIR = ROOT / 'assets' / 'scenarios' / 'volleyball_corner_rebound'\nMODELS = ROOT / 'assets' / 'models'\n\n# Scene-control keys carry the in-run edit schedule rather than a measurement\n# of the room: they are absent from scenario.json, and every case has one\n# (empty unless the case carries a timed edit). Defaulting them before the\n# override patch is applied is what makes a schedule a legal physics override.\nSCENE_CONTROL_DEFAULTS = {'timed_edits': []}\n\ndef load_scenario(overrides=None):\n    result = json.loads((SCENARIO_DIR / 'scenario.json').read_text(encoding='utf-8'))\n    for key, value in SCENE_CONTROL_DEFAULTS.items():\n        result['physics'].setdefault(key, copy.deepcopy(value))\n    if overrides is not None:\n        patch = json.loads(Path(overrides).read_text(encoding='utf-8')) if isinstance(overrides, (str, Path)) else copy.deepcopy(overrides)\n        for section, values in patch.items():\n            if section not in result or not isinstance(values, dict):\n                raise ValueError(f'Unsupported scenario section: {section}')\n            unknown = set(values) - set(result[section])\n            if unknown:\n                raise ValueError(f'Unknown {section} keys: {sorted(unknown)}')\n            result[section].update(values)\n    p = result['physics']\n    for key in ('fps', 'duration_sec', 'substeps_per_frame', 'ball_mass', 'ball_radius', 'ball_initial_speed'):\n        if not math.isfinite(float(p[key])) or p[key] <= 0:\n            raise ValueError(f'{key} must be positive and finite')\n    for key in ('ball_restitution', 'floor_restitution', 'wall_restitution'):\n        if not 0 <= p[key] <= 1:\n            raise ValueError(f'{key} must be in [0, 1]')\n    for key in ('ball_friction', 'ball_rolling_friction', 'ball_spinning_friction', 'floor_friction', 'floor_rolling_friction', 'wall_friction', 'linear_damping', 'angular_damping'):\n        if not math.isfinite(float(p[key])) or p[key] < 0:\n            raise ValueError(f'{key} must be nonnegative and finite')\n    if len(p['room_size']) != 3 or min(p['room_size']) <= 0:\n        raise ValueError('room_size must contain three positive dimensions')\n    if len(p['launch_direction']) != 3 or not all(math.isfinite(v) for v in p['launch_direction']) or math.hypot(*p['launch_direction']) == 0:\n        raise ValueError('Nonzero finite launch_direction XYZ required')\n    if len(p['ball_initial_angular_velocity']) != 3 or not all(math.isfinite(v) for v in p['ball_initial_angular_velocity']):\n        raise ValueError('Finite initial angular velocity XYZ required')\n    if len(p['ball_initial_location']) != 3 or any(not math.isfinite(v) or not p['ball_radius'] < v < extent-p['ball_radius'] for v, extent in zip(p['ball_initial_location'], p['room_size'])):\n        raise ValueError('Ball starts outside the room or intersects a wall')\n    if 2*p['ball_radius'] >= p['room_size'][2]:\n        raise ValueError('Ball must fit below the ceiling')\n    return result\n\ndef write_json(path, value):\n    path = Path(path)\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(value, ensure_ascii=False, indent=2, allow_nan=False), encoding='utf-8')\n\ndef runtime(kind):\n    relative = 'render/Scripts/python.exe' if kind == 'render' else 'sim/python.exe'\n    for root in (ROOT, ROOT.parent / 'PCVE-ElasticBench'):\n        path = root / '.runtime' / relative\n        if path.is_file():\n            return str(path)\n    raise FileNotFoundError(f'No {kind} Python runtime; use an environment with bpy/pybullet')\n", "volleyball_corner_rebound.scene_environment": "\"\"\"Photographic materials and metre-scale architectural room, authored locally.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport math\nfrom pathlib import Path\nROOT = _PCVE_ROOT\nimport bpy\nfrom mathutils import Vector\nfrom scene_config import MODELS\nfrom scene_geometry import (AC_BACK_GAP, AC_CENTER, AC_HEIGHT, AC_WIDTH, CABINET_CENTER,\n    CABINET_SIZE, SPARE_BALL_CENTERS, SPARE_BALL_RADIUS, WINDOW_CENTER_Y)\n\n# cafe_wall_pictures.glb stacks three pictures on one shared 0.49 x 0.33 m mesh that\n# differ only in texture, so choosing the artwork is a name lookup: wall and frame\n# geometry stay put.  Picture 1 is a photo-real window-and-coffee-jar still life, its\n# dark frame and busy interior collapsing into a brown smudge at the size the far\n# camera gives it; picture 3 is a coffee-bean owl on cream that vanishes against the\n# pale wall; picture 2 is a copper mug on a flat blush ground and still reads as a\n# picture from across the room.\nPICTURE_MESH = 'wall_picture_2'\n\ndef material(name, color, roughness=.6, bump=.0):\n    mat = bpy.data.materials.new(name)\n    mat.diffuse_color = (*color, 1)\n    mat.use_nodes = True\n    nodes, links = mat.node_tree.nodes, mat.node_tree.links\n    bsdf = nodes.get('Principled BSDF')\n    bsdf.inputs['Base Color'].default_value = (*color, 1)\n    bsdf.inputs['Roughness'].default_value = roughness\n    if bump:\n        coord = nodes.new('ShaderNodeTexCoord')\n        noise = nodes.new('ShaderNodeTexNoise')\n        noise.inputs['Scale'].default_value = 170\n        noise.inputs['Detail'].default_value = 2\n        links.new(coord.outputs['Object'], noise.inputs['Vector'])\n        node = nodes.new('ShaderNodeBump')\n        node.inputs['Strength'].default_value = .22\n        node.inputs['Distance'].default_value = bump\n        links.new(noise.outputs['Fac'], node.inputs['Height'])\n        links.new(node.outputs['Normal'], bsdf.inputs['Normal'])\n    return mat\n\ndef cube(name, center, size, mat, bevel=0):\n    bpy.ops.mesh.primitive_cube_add(size=1, location=center)\n    obj = bpy.context.object\n    obj.name = name\n    obj.dimensions = size\n    bpy.ops.object.transform_apply(location=False, rotation=False, scale=True)\n    obj.data.materials.append(mat)\n    if bevel:\n        mod = obj.modifiers.new('Soft manufactured edges', 'BEVEL')\n        mod.width, mod.segments = bevel, 3\n        obj.modifiers.new('Weighted normals', 'WEIGHTED_NORMAL')\n    return obj\n\ndef aim(obj, point):\n    obj.rotation_euler = (Vector(point)-obj.location).to_track_quat('-Z','Y').to_euler()\n\ndef area(name, pos, target, power, size, color=(1,.89,.75)):\n    data = bpy.data.lights.new(name, 'AREA')\n    data.energy, data.shape, data.size, data.color = power, 'DISK', size, color\n    # These broad sources approximate bounced daylight, not visible fixtures.\n    # The HDR and room geometry provide the actual glass reflections.\n    data.specular_factor=0\n    obj = bpy.data.objects.new(name,data)\n    bpy.context.collection.objects.link(obj)\n    obj.location = pos\n    obj.visible_glossy=False\n    aim(obj,target)\n    return obj\n\ndef floor_material(path):\n    mat = material('Oak boards / scanned worn wood', (.32,.19,.09), .48)\n    nodes, links = mat.node_tree.nodes, mat.node_tree.links\n    bsdf = nodes.get('Principled BSDF')\n    uv = nodes.new('ShaderNodeTexCoord')\n    sep = nodes.new('ShaderNodeSeparateXYZ')\n    links.new(uv.outputs['Object'],sep.inputs[0])\n    combine = nodes.new('ShaderNodeCombineXYZ')\n    for axis in ('X','Y'):\n        scale = nodes.new('ShaderNodeMath')\n        scale.operation = 'MULTIPLY'\n        scale.inputs[1].default_value = .62\n        links.new(sep.outputs[axis],scale.inputs[0])\n        links.new(scale.outputs[0],combine.inputs[axis])\n    image = nodes.new('ShaderNodeTexImage')\n    image.image = bpy.data.images.load(str(path), check_existing=True)\n    image.extension = 'REPEAT'\n    links.new(combine.outputs[0],image.inputs['Vector'])\n    links.new(image.outputs['Color'],bsdf.inputs['Base Color'])\n    bump = nodes.new('ShaderNodeBump')\n    bump.inputs['Strength'].default_value = .18\n    bump.inputs['Distance'].default_value = .002\n    links.new(image.outputs['Color'],bump.inputs['Height'])\n    links.new(bump.outputs['Normal'],bsdf.inputs['Normal'])\n    return mat\n\ndef terrazzo_material():\n    mat=material('Fine warm-grey terrazzo / 1 m slabs',(.25,.265,.26),.49)\n    nodes,links=mat.node_tree.nodes,mat.node_tree.links\n    bsdf=nodes.get('Principled BSDF')\n    coord=nodes.new('ShaderNodeTexCoord')\n    chips=nodes.new('ShaderNodeTexVoronoi')\n    chips.inputs['Scale'].default_value=35\n    chips.distance='EUCLIDEAN'\n    links.new(coord.outputs['Object'],chips.inputs['Vector'])\n    gate=nodes.new('ShaderNodeMath')\n    gate.operation='LESS_THAN'\n    gate.inputs[1].default_value=.36\n    links.new(chips.outputs['Distance'],gate.inputs[0])\n    palette=nodes.new('ShaderNodeValToRGB')\n    palette.color_ramp.interpolation='CONSTANT'\n    for index,(position,color) in enumerate(((0,(.055,.065,.06,1)),(.35,(.24,.19,.14,1)),(.5,(.43,.45,.43,1)),(.7,(.62,.60,.54,1)))):\n        element=palette.color_ramp.elements[index] if index<2 else palette.color_ramp.elements.new(position)\n        element.position=position\n        element.color=color\n    links.new(chips.outputs['Color'],palette.inputs[0])\n    mix=nodes.new('ShaderNodeMixRGB')\n    mix.inputs[1].default_value=(.25,.265,.26,1)\n    links.new(gate.outputs[0],mix.inputs[0])\n    links.new(palette.outputs['Color'],mix.inputs[2])\n    separate=nodes.new('ShaderNodeSeparateXYZ')\n    links.new(coord.outputs['Object'],separate.inputs[0])\n    seams=[]\n    for axis in ('X','Y'):\n        fract=nodes.new('ShaderNodeMath')\n        fract.operation='FRACT'\n        links.new(separate.outputs[axis],fract.inputs[0])\n        seam=nodes.new('ShaderNodeMath')\n        seam.operation='LESS_THAN'\n        seam.inputs[1].default_value=.003\n        links.new(fract.outputs[0],seam.inputs[0])\n        seams.append(seam)\n    combine=nodes.new('ShaderNodeMath')\n    combine.operation='MAXIMUM'\n    for index,seam in enumerate(seams):\n        links.new(seam.outputs[0],combine.inputs[index])\n    grout=nodes.new('ShaderNodeMixRGB')\n    links.new(combine.outputs[0],grout.inputs[0])\n    links.new(mix.outputs[0],grout.inputs[1])\n    grout.inputs[2].default_value=(.11,.12,.11,1)\n    links.new(grout.outputs[0],bsdf.inputs['Base Color'])\n    grain=nodes.new('ShaderNodeTexNoise')\n    grain.inputs['Scale'].default_value=220\n    grain.inputs['Detail'].default_value=2\n    links.new(coord.outputs['Object'],grain.inputs['Vector'])\n    bump=nodes.new('ShaderNodeBump')\n    bump.inputs['Strength'].default_value=.13\n    bump.inputs['Distance'].default_value=.00022\n    links.new(grain.outputs['Fac'],bump.inputs['Height'])\n    links.new(bump.outputs['Normal'],bsdf.inputs['Normal'])\n    return mat\n\ndef porcelain_floor(width, depth):\n    \"\"\"Metre-scale ceramic slabs, with quiet surface variation and real joints.\"\"\"\n    grout=material('Warm grey fine grout',(.24,.23,.21),.82)\n    cube('Floor structural base',(width/2,depth/2,-.08),(width,depth,.12),grout)\n    finishes=[]\n    for index,offset in enumerate((-.012,-.006,0,.006,.012)):\n        mat=material(f'Matte limestone porcelain / tone {index}',(.38+offset,.365+offset,.335+offset),.47)\n        nodes,links=mat.node_tree.nodes,mat.node_tree.links\n        shader=nodes.get('Principled BSDF')\n        coord=nodes.new('ShaderNodeTexCoord')\n        cloud=nodes.new('ShaderNodeTexNoise')\n        cloud.inputs['Scale'].default_value=2.3\n        cloud.inputs['Detail'].default_value=2\n        cloud.inputs['Roughness'].default_value=.55\n        links.new(coord.outputs['Object'],cloud.inputs['Vector'])\n        ramp=nodes.new('ShaderNodeValToRGB')\n        ramp.color_ramp.elements[0].color=(.36+offset,.345+offset,.316+offset,1)\n        ramp.color_ramp.elements[1].color=(.40+offset,.385+offset,.354+offset,1)\n        links.new(cloud.outputs['Fac'],ramp.inputs[0])\n        links.new(ramp.outputs[0],shader.inputs['Base Color'])\n        fine=nodes.new('ShaderNodeTexNoise')\n        fine.inputs['Scale'].default_value=360\n        fine.inputs['Detail'].default_value=1\n        links.new(coord.outputs['Object'],fine.inputs['Vector'])\n        bump=nodes.new('ShaderNodeBump')\n        bump.inputs['Strength'].default_value=.10\n        bump.inputs['Distance'].default_value=.00005\n        links.new(fine.outputs['Fac'],bump.inputs['Height'])\n        links.new(bump.outputs[0],shader.inputs['Normal'])\n        finishes.append(mat)\n    size=1.2\n    gap=.002\n    for ix in range(math.ceil(width/size)):\n        for iy in range(math.ceil(depth/size)):\n            sx=min(size,width-ix*size)\n            sy=min(size,depth-iy*size)\n            tile=cube(f'Porcelain slab {ix:02d}-{iy:02d}',\n                (ix*size+sx/2,iy*size+sy/2,-.01),(sx-gap,sy-gap,.02),\n                finishes[(ix*7+iy*13)%len(finishes)],.0007)\n            # World-space texture coordinates avoid repeating a pattern per slab.\n            texture_origin=bpy.data.objects.get('Floor texture coordinates')\n            if texture_origin is None:\n                texture_origin=bpy.data.objects.new('Floor texture coordinates',None)\n                bpy.context.collection.objects.link(texture_origin)\n                for mat in finishes:\n                    mat.node_tree.nodes.get('Texture Coordinate').object=texture_origin\n\ndef build_window():\n    \"\"\"A recessed casement in a real wall opening; no emissive glass.\"\"\"\n    before=set(bpy.data.objects)\n    frame=material('Window / satin off-white aluminium',(.65,.67,.65),.3)\n    reveal=material('Window / plaster reveal',(.59,.61,.57),.8)\n    gasket=material('Window / EPDM seals',(.026,.031,.028),.72)\n    sill=material('Window / honed limestone sill',(.48,.465,.43),.43,.00015)\n    # Opening is y=2.8..4.2 and z=1.13..2.63, through a 20 cm wall.\n    for y in (2.8,4.2):\n        cube('Window plaster jamb',(-.10,y,1.88),(.2,.035,1.50),reveal,.002)\n    cube('Window plaster head',(-.10,3.5,2.63),(.2,1.4,.035),reveal,.002)\n    for y in (2.84,4.16):\n        cube('Window outer frame / jamb',(-.105,y,1.88),(.075,.065,1.43),frame,.004)\n    for z in (1.17,2.59):\n        cube('Window outer frame / rail',(-.105,3.5,z),(.075,1.38,.065),frame,.004)\n    cube('Window central mullion',(-.087,3.5,1.88),(.082,.055,1.40),frame,.003)\n    glass=material('Window / clear double glazing',(.97,.985,1.0),.012)\n    shader=glass.node_tree.nodes.get('Principled BSDF')\n    shader.inputs['Transmission Weight'].default_value=1\n    shader.inputs['IOR'].default_value=1.46\n    for yc in (3.17,3.83):\n        for y in (yc-.285,yc+.285):\n            cube('Casement rubber seal',(-.090,y,1.88),(.016,.012,1.31),gasket,.001)\n        for z in (1.23,2.53):\n            cube('Casement rubber seal',(-.090,yc,z),(.016,.58,.012),gasket,.001)\n        cube('Window glass / transparent pane',(-.115,yc,1.88),(.004,.57,1.29),glass)\n    cube('Stone sill / projecting eased edge',(.025,3.5,1.11),(.34,1.52,.045),sill,.005)\n    metal=material('Window / brushed nickel hardware',(.36,.38,.37),.24)\n    metal.node_tree.nodes.get('Principled BSDF').inputs['Metallic'].default_value=.8\n    cube('Window handle base',(-.032,3.55,1.81),(.022,.025,.06),metal,.004)\n    cube('Window handle lever',(-.009,3.55,1.77),(.024,.018,.10),metal,.006)\n    # Daylight enters from outside the aperture; the frame casts real shadows.\n    light=area('Overcast daylight through opening',(-2.0,3.3,4.2),(1.5,2.5,.3),650,1.4,(.88,.94,1))\n    light.data.shape='RECTANGLE'\n    light.data.size=1.25\n    light.data.size_y=1.25\n    light.visible_camera=False\n    light.visible_glossy=False\n    light.visible_transmission=False\n    for obj in set(bpy.data.objects)-before:\n        obj.location.y+=WINDOW_CENTER_Y-3.5\n\ndef build_room(scenario):\n    w,d,h = scenario['physics']['room_size']\n    plaster = material('Warm chalk plaster',(.59,.57,.51),.86,.0012)\n    plaster_side = material('Muted sage limewash',(.31,.39,.34),.9,.0012)\n    trim = material('Painted ivory joinery',(.72,.70,.64),.48,.0003)\n    dark = material('Charcoal metal',(.025,.03,.029),.38)\n    oak = material('Natural oak frame',(.22,.115,.055),.5,.0005)\n    add_oak_grain(oak)\n    paper = material('Uncoated art paper',(.69,.64,.52),.95)\n    terracotta = material('Clay pigment',(.33,.12,.065),.95)\n    # Extend the display floor past the camera-side cutaway to avoid exposed edges.\n    visual_w, visual_d=max(w,12),max(d,12)\n    if scenario['assets']['floor']=='matte_limestone_porcelain':\n        porcelain_floor(visual_w,visual_d)\n    else:\n        floor_mat=terrazzo_material() if scenario['assets']['floor']=='procedural_fine_terrazzo' else floor_material(ROOT/'assets'/'polyhaven'/'volleyball_corner_rebound'/scenario['assets']['floor'])\n        cube('Floor', (visual_w/2,visual_d/2,-.1),(visual_w,visual_d,.2),floor_mat)\n    # Partition the wall around the actual window opening, retaining the solid\n    # impact face elsewhere. The glazing closes the unchanged collision plane.\n    for name,center,size in (\n        ('Wall_X / corner side',(-.1,(WINDOW_CENTER_Y-.7)/2,(h+.07)/2),(.2,WINDOW_CENTER_Y-.7,h-.07)),\n        ('Wall_X / outer side',(-.1,(WINDOW_CENTER_Y+.7+d)/2,(h+.07)/2),(.2,d-WINDOW_CENTER_Y-.7,h-.07)),\n        ('Wall_X / below window',(-.1,WINDOW_CENTER_Y,.60),(.2,1.4,1.06)),\n        ('Wall_X / above window',(-.1,WINDOW_CENTER_Y,(2.63+h)/2),(.2,1.4,h-2.63))):\n        cube(name,center,size,plaster_side)\n    cube('Wall_Y / impact face y=0',(w/2,-.1,(h+.07)/2),(w,.2,h-.07),plaster)\n    cube('Far wall X / physical boundary',(w+.1,d/2,h/2),(.2,d,h),plaster_side)\n    cube('Far wall Y / physical boundary',(w/2,d+.1,h/2),(w,.2,h),plaster)\n    # Lit only by the sky and the daylight through the window (see\n    # exempt_slab_from_fills), so its albedo carries the whole tone: 0.73\n    # was tuned against a slab that the interior fills also brushed.\n    ceiling=material('Ceiling / soft white plaster',(.88,.868,.832),.9)\n    cube('Interior ceiling',(w/2,d/2,h+.08),(w,d,.16),ceiling)\n    # Flush skirting: faces match the physics planes exactly, no visual protrusion.\n    cube('Flush skirting X',(-.1,d/2,.035),(.2,d,.07),trim)\n    cube('Flush skirting Y',(w/2,-.1,.035),(w,.2,.07),trim)\n    import_wall_art(MODELS/scenario['assets']['paintings'])\n    import_air_conditioner(MODELS/scenario['assets']['air_conditioner'])\n    build_background(oak,trim,dark,terracotta,plaster_side)\n    build_spare_balls(MODELS/scenario['assets']['ball'])\n    # Outlet is on a part of the wall away from the ball trajectory.\n    cube('Outlet face',(.004,2.9,.36),(.008,.085,.085),trim,.003)\n    for yy in (2.88,2.92):\n        cube('Outlet socket',(.009,yy,.36),(.003,.007,.016),dark,.001)\n    build_window()\n    area('Soft room fill',(4.2,4.5,2.88),(2.4,2.4,.2),200,3.5,(1,.96,.9))\n    area('Ceiling bounce',(1.7,1.7,2.85),(1.2,1,.0),90,2.4,(1,.97,.92))\n    # A broad, fixed fill lifts the foreground boards and the camera-facing\n    # side of the ball throughout the trajectory, without tracking the ball.\n    area('Broad foreground and ball fill',(7.0,5.8,2.65),(3.2,3.2,.8),120,3.5,(1,.97,.93))\n    scene = bpy.context.scene\n    scene.world = bpy.data.worlds.new('Quiet ambient interior')\n    scene.world.use_nodes=True\n    nodes,links=scene.world.node_tree.nodes,scene.world.node_tree.links\n    environment=nodes.new('ShaderNodeTexEnvironment')\n    environment.image=bpy.data.images.load(str(ROOT/'assets'/'polyhaven'/'volleyball_corner_rebound'/'overcast_industrial_courtyard_4k.hdr'),check_existing=True)\n    coord=nodes.new('ShaderNodeTexCoord')\n    mapping=nodes.new('ShaderNodeMapping')\n    mapping.inputs['Rotation'].default_value[2]=math.radians(270)\n    links.new(coord.outputs['Generated'],mapping.inputs['Vector'])\n    links.new(mapping.outputs[0],environment.inputs['Vector'])\n    links.new(environment.outputs['Color'],nodes['Background'].inputs['Color'])\n    nodes['Background'].inputs['Strength'].default_value=1.1\n\ndef cylinder(name, center, radius, depth, mat):\n    bpy.ops.mesh.primitive_cylinder_add(vertices=48,radius=radius,depth=depth,location=center)\n    obj=bpy.context.object\n    obj.name=name\n    obj.data.materials.append(mat)\n    for face in obj.data.polygons:\n        face.use_smooth=True\n    bevel=obj.modifiers.new('Ceramic rounded rim','BEVEL')\n    bevel.width=.007\n    bevel.segments=3\n    obj.modifiers.new('Weighted normals','WEIGHTED_NORMAL')\n    return obj\n\ndef add_oak_grain(mat):\n    nodes,links=mat.node_tree.nodes,mat.node_tree.links\n    if nodes.get('Oak grain color'):\n        return\n    coord=nodes.new('ShaderNodeTexCoord')\n    scale=nodes.new('ShaderNodeVectorMath')\n    scale.operation='MULTIPLY'\n    scale.inputs[1].default_value=(1.5,65,6)\n    links.new(coord.outputs['Object'],scale.inputs[0])\n    noise=nodes.new('ShaderNodeTexNoise')\n    noise.inputs['Scale'].default_value=3.0\n    noise.inputs['Detail'].default_value=2\n    links.new(scale.outputs['Vector'],noise.inputs['Vector'])\n    ramp=nodes.new('ShaderNodeValToRGB')\n    ramp.name='Oak grain color'\n    ramp.color_ramp.elements[0].position=.15\n    ramp.color_ramp.elements[0].color=(.17,.083,.033,1)\n    ramp.color_ramp.elements[1].position=.85\n    ramp.color_ramp.elements[1].color=(.29,.16,.075,1)\n    links.new(noise.outputs['Fac'],ramp.inputs[0])\n    links.new(ramp.outputs['Color'],nodes.get('Principled BSDF').inputs['Base Color'])\n\ndef build_background(oak,trim,dark,clay,sage):\n    x,y,z=CABINET_CENTER\n    w,d,h=CABINET_SIZE\n    cube('Closed oak sideboard',CABINET_CENTER,CABINET_SIZE,oak,.009)\n    front=y+d/2\n    for xx in (x-w/4,x+w/4):\n        cube('Recessed cabinet door',(xx,front+.002,z),(.70,.005,h-.11),oak,.003)\n        cube('Slim cabinet handle',(xx+.23,front+.015,z+.13),(.016,.026,.09),dark,.004)\n    book_colors=((.12,.19,.24),(.53,.28,.16),(.59,.57,.45))\n    top=h\n    for i,color in enumerate(book_colors):\n        cover=material(f'Clothbound book {i}',color,.85,.0005)\n        bx=x-.36+(.025 if i==1 else 0)\n        bz=top+.02+i*.038\n        cube('Book paper block',(bx,y+.005,bz),(.31,.105,.029),trim,.002)\n        for delta in (-.017,.017):\n            cube('Book cloth cover',(bx,y+.005,bz+delta),(.33,.12,.005),cover,.002)\n    cylinder('Earthenware vase',(x+.38,y,h+.15),.095,.30,clay)\n    cylinder('Vase dark opening',(x+.38,y,h+.302),.058,.002,dark)\n    # The corner is left empty: no planter, no foliage, nothing to trip the ball.\n\ndef exempt_slab_from_fills():\n    \"\"\"Let the ceiling hear the daylight and the sky, but not the interior fills.\n\n    The three interior fills are 2.4-3.5 m disks hanging 0.12-0.35 m under the\n    slab and tilted 45-70 degrees, so the rim of every one of them pokes up\n    through it -- `cz + r * sqrt(1 - nz^2)` puts their top edges at 3.19, 4.13 and\n    4.28 m against a slab whose underside is at 3.00 m.  Every other surface is\n    lit by the disk's face and does not care.  The slab is lit only by the rim,\n    at grazing angles, which is what the blotch on the ceiling is: measured over\n    the slab, the interior fills alone give mean 51.8 with std 18.8, while the\n    sky and the window daylight alone give a flat 0.4.\n\n    Light linking states that directly instead of moving lights that everything\n    else depends on.  Called once the whole shot exists, because the receiver\n    collection has to hold every object that is not the slab.\n    \"\"\"\n    slab = bpy.data.objects.get('Interior ceiling')\n    if slab is None or not hasattr(slab, 'light_linking'):\n        return None\n    existing = bpy.data.collections.get('Lit by the interior fills')\n    if existing is not None:\n        return existing\n    receivers = bpy.data.collections.new('Lit by the interior fills')\n    bpy.context.scene.collection.children.link(receivers)\n    for obj in bpy.context.scene.objects:\n        if obj is not slab:\n            receivers.objects.link(obj)\n    for obj in bpy.context.scene.objects:\n        if obj.type == 'LIGHT' and 'Overcast' not in obj.name:\n            obj.light_linking.receiver_collection = receivers\n    return receivers\n\n\ndef build_spare_balls(path):\n    first=import_ball(path,SPARE_BALL_RADIUS)\n    first.name='Spare volleyball 1 / static'\n    for index,position in enumerate(SPARE_BALL_CENTERS):\n        body=first if index==0 else first.copy()\n        if index:\n            body.data=first.data.copy()\n            bpy.context.collection.objects.link(body)\n        body.name=f'Spare volleyball {index+1} / static'\n        body.animation_data_clear()\n        body.location=position\n        body.rotation_mode='XYZ'\n        body.rotation_euler=((.4,.9,.2),(1.2,.3,2.1))[index]\n\ndef import_wall_art(path):\n    from mathutils import Matrix\n    before=set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(path))\n    bpy.context.view_layer.update()\n    imported=[o for o in bpy.data.objects if o not in before]\n    candidates=sorted([o for o in imported if o.type=='MESH' and 'wall_picture' in o.name],key=lambda o:o.name)\n    if not candidates:\n        raise ValueError('No framed picture meshes in cafe_wall_pictures.glb')\n    chosen=sorted([o for o in candidates if o.name.startswith(PICTURE_MESH)],key=lambda o:o.name)\n    original=(chosen or candidates)[0]\n    rotation=Matrix.Rotation(math.pi/2,4,'Z')\n    for index,(x,z,height) in enumerate(((3.0,1.75,.90),)):\n        mesh=original.data.copy()\n        mesh.transform(rotation@original.matrix_world)\n        lo=Vector(tuple(min(v.co[i] for v in mesh.vertices) for i in range(3)))\n        hi=Vector(tuple(max(v.co[i] for v in mesh.vertices) for i in range(3)))\n        origin=Vector(((lo.x+hi.x)/2,lo.y,(lo.z+hi.z)/2))\n        scale=height/(hi.z-lo.z)\n        for vertex in mesh.vertices:\n            vertex.co=(vertex.co-origin)*scale+Vector((x,.006,z))\n        body=bpy.data.objects.new(f'Imported framed art {index+1} / {original.name}',mesh)\n        bpy.context.collection.objects.link(body)\n        for mat in mesh.materials:\n            if mat and mat.use_nodes:\n                for node in mat.node_tree.nodes:\n                    if node.type=='BSDF_PRINCIPLED':\n                        node.inputs['Emission Strength'].default_value=0\n    for obj in imported:\n        bpy.data.objects.remove(obj,do_unlink=True)\n\ndef import_air_conditioner(path):\n    from mathutils import Matrix\n    before=set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(path))\n    imported=[o for o in bpy.data.objects if o not in before]\n    meshes=[o for o in imported if o.type=='MESH']\n    if not meshes:\n        raise ValueError('Indoor unit asset contains no meshes')\n    bpy.ops.object.select_all(action='DESELECT')\n    for obj in meshes:\n        obj.animation_data_clear()\n        obj.select_set(True)\n    bpy.context.view_layer.objects.active=meshes[0]\n    if len(meshes)>1:\n        bpy.ops.object.join()\n    body=bpy.context.object\n    world=body.matrix_world.copy()\n    body.parent=None\n    body.matrix_world=world\n    for obj in imported:\n        if obj!=body and obj.name in bpy.data.objects:\n            bpy.data.objects.remove(obj,do_unlink=True)\n    bpy.ops.object.transform_apply(location=True,rotation=True,scale=True)\n    # The asset's back is its +Y face and the louvre panel faces -Y.  The wall it\n    # goes on is x=0 with the room on +X, so a quarter turn about Z (+Y -> -X)\n    # lays the back on the plaster and points the panel into the room; the unit's\n    # width then runs along Y and its depth along X, which is why AC_SIZE swaps\n    # the two.  Width, not height, is what a split is specified by, so that is\n    # the one dimension the uniform scale is pinned to.\n    body.data.transform(Matrix.Rotation(math.pi/2,4,'Z'))\n    lo=Vector(tuple(min(v.co[i] for v in body.data.vertices) for i in range(3)))\n    hi=Vector(tuple(max(v.co[i] for v in body.data.vertices) for i in range(3)))\n    factor=AC_WIDTH/(hi.y-lo.y)\n    centre=Vector((lo.x,(lo.y+hi.y)*.5,(lo.z+hi.z)*.5))\n    for vertex in body.data.vertices:\n        vertex.co=(vertex.co-centre)*factor+Vector((AC_BACK_GAP,AC_CENTER[1],AC_CENTER[2]))\n    body.location=(0,0,0)\n    body.name='Split indoor unit'\n    for poly in body.data.polygons:\n        poly.use_smooth=True\n    for mat in body.data.materials:\n        if not mat or not mat.use_nodes:\n            continue\n        for node in mat.node_tree.nodes:\n            if node.type=='BSDF_PRINCIPLED':\n                node.inputs['Emission Strength'].default_value=0\n                # The glb's packed metallic channel reads 0.91 over the painted\n                # shell, which is an authoring slip rather than the object: a\n                # split indoor unit is painted steel and plastic.  Under this\n                # overcast HDR that value turns it into a mirror and it renders\n                # blue-grey, so metallic is pinned to 0.  Roughness keeps the\n                # supplied map, so the sheen is still the asset's own.\n                for link in list(node.inputs['Metallic'].links):\n                    mat.node_tree.links.remove(link)\n                node.inputs['Metallic'].default_value=0\n\ndef import_ball(path, radius):\n    before=set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(path))\n    imported=[o for o in bpy.data.objects if o not in before]\n    meshes=[o for o in imported if o.type=='MESH']\n    if not meshes:\n        raise ValueError('Volleyball asset contains no meshes')\n    bpy.ops.object.select_all(action='DESELECT')\n    for obj in meshes:\n        obj.animation_data_clear()\n        obj.select_set(True)\n    bpy.context.view_layer.objects.active=meshes[0]\n    if len(meshes)>1:\n        bpy.ops.object.join()\n    ball=bpy.context.object\n    world=ball.matrix_world.copy()\n    ball.parent=None\n    ball.matrix_world=world\n    for obj in imported:\n        if obj!=ball and obj.name in bpy.data.objects:\n            bpy.data.objects.remove(obj,do_unlink=True)\n    bpy.ops.object.transform_apply(location=True,rotation=True,scale=True)\n    # Bounding sphere centre, so the visual centre matches GEOM_SPHERE.\n    lo=Vector(tuple(min(v.co[i] for v in ball.data.vertices) for i in range(3)))\n    hi=Vector(tuple(max(v.co[i] for v in ball.data.vertices) for i in range(3)))\n    center=(lo+hi)*.5\n    factor=2*radius/max(hi-lo)\n    for vertex in ball.data.vertices:\n        vertex.co=(vertex.co-center)*factor\n    ball.location=(0,0,0)\n    ball.name='volleyball'\n    for poly in ball.data.polygons:\n        poly.use_smooth=True\n    for mat in ball.data.materials:\n        if not mat or not mat.use_nodes:\n            continue\n        for node in mat.node_tree.nodes:\n            if node.type=='BSDF_PRINCIPLED':\n                node.inputs['Emission Strength'].default_value=0\n                if not node.inputs['Roughness'].is_linked:\n                    node.inputs['Roughness'].default_value=.68\n    return ball\n", "volleyball_corner_rebound.scene_geometry": "\"\"\"Shared visual/physics dimensions of room furniture and static spare balls.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nCABINET_CENTER=(3.8,.11,.21)\nCABINET_SIZE=(1.5,.20,.42)\n# There is no plant in this room. The corner the ball rebounds into is the only\n# corner the camera can see, so a planter there would be a collider the two\n# low-restitution edits roll into; a planter anywhere else is either out of shot\n# or standing in front of the window. The corner is left empty instead, which is\n# also what the ball's own story needs: it comes to rest against the walls.\nSPARE_BALL_RADIUS=.105\n# Parked at the far end of the sideboard, clear of every run: at their old\n# spot the 1.5x speed edit passed a spare ball by 0.2 mm.\nSPARE_BALL_CENTERS=((4.75,.30,SPARE_BALL_RADIUS),(4.95,.80,SPARE_BALL_RADIUS))\nWINDOW_CENTER_Y=2.5\n# The split indoor unit hangs on the window wall, x=0, the wall the camera faces\n# most squarely: seen from the y=0 wall its face was foreshortened to 0.56 of its\n# length, here it keeps 0.95.  indoor_air_conditioner_unit imports as\n# 0.531 x 0.131 x 0.181 m; the room is 10 x 8 x 3 m = 240 m3, which a 3 HP wall\n# split of about 1.10 x 0.25 x 0.33 m serves, so the asset is scaled uniformly by\n# 2.26 to 1.20 m wide (0.409 high, 0.296 deep) and its own proportions are kept\n# rather than stretched to the figures.\nAC_SCALE=2.26\nAC_WIDTH=.531*AC_SCALE\nAC_DEPTH=.131*AC_SCALE\nAC_HEIGHT=.181*AC_SCALE\nAC_BACK_GAP=.006\n# Hung with its underside 2.40 m up and 0.90 m clear of the window's right reveal\n# at y=3.20, which puts the top of the case at 2.81 m: 0.19 m of clearance to the\n# 3.0 m ceiling, the gap the install manuals ask for and the reason the unit\n# cannot go higher.  Its own width runs along the wall (y) and its depth along x:\n# AC_SIZE is the axis-aligned box the simulator collides with, so width and depth\n# swap relative to the brief's W x D x H.\nAC_WALL_Y=4.70\nAC_BOTTOM_Z=2.40\nAC_CENTER=(AC_BACK_GAP+AC_DEPTH/2,AC_WALL_Y,AC_BOTTOM_Z+AC_HEIGHT/2)\nAC_SIZE=(AC_DEPTH,AC_WIDTH,AC_HEIGHT)\n\ndef geometry_snapshot():\n    return {'cabinet_center':list(CABINET_CENTER),'cabinet_size':list(CABINET_SIZE),\n        'spare_ball_radius':SPARE_BALL_RADIUS,'spare_ball_centers':[list(p) for p in SPARE_BALL_CENTERS],\n        'window_center_y':WINDOW_CENTER_Y,\n        'ac_center':list(AC_CENTER),'ac_size':list(AC_SIZE)}\n", "volleyball_corner_rebound": "from pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n"}""")

_BUNDLE_SCENE_ALIAS = 'volleyball_corner_rebound'
_BUNDLE_ALIASES = ['camera_rig', 'scene_config', 'scene_environment', 'scene_geometry', 'volleyball_corner_rebound', 'volleyball_corner_rebound.camera_rig', 'volleyball_corner_rebound.scene_config', 'volleyball_corner_rebound.scene_environment', 'volleyball_corner_rebound.scene_geometry']

class _SceneBundleLoader(_bundle_abc.MetaPathFinder, _bundle_abc.Loader):
    def find_spec(self, fullname, path=None, target=None):
        if fullname not in _BUNDLE_SOURCES:
            return None
        package = (fullname == "scene_support" or fullname.count(".") == 1 and fullname.startswith("scene_support.") or fullname == _BUNDLE_SCENE_ALIAS)
        return _bundle_util.spec_from_loader(fullname, self, is_package=package)

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        name = module.__spec__.name
        package = module.__spec__.submodule_search_locations is not None
        if name == "scene_support":
            origin = _BUNDLE_SCENE / "scene_support" / "__init__.py"
        elif name == _BUNDLE_SCENE_ALIAS:
            origin = _BUNDLE_SCENE / "scene_support" / name / "__init__.py"
        elif name.startswith(_BUNDLE_SCENE_ALIAS + "."):
            origin = _BUNDLE_SCENE / "scene_support" / name.replace(".", "/")
            origin = origin.with_suffix(".py")
        elif name.startswith("scene_support."):
            tail = name.split(".", 1)[1]
            if package:
                origin = _BUNDLE_SCENE / "scene_support" / tail / "__init__.py"
            else:
                origin = _BUNDLE_SCENE / "scene_support" / tail.replace(".", "/")
                origin = origin.with_suffix(".py")
        else:
            origin = _BUNDLE_SCRIPTS / (name + ".py")
        module.__file__ = str(origin)
        module.__package__ = name if package else (_BUNDLE_SCENE_ALIAS if name.startswith(_BUNDLE_SCENE_ALIAS + ".") or name in ['camera_rig', 'scene_config', 'scene_environment', 'scene_geometry'] else name.rpartition("." )[0])
        if package:
            module.__path__ = [str(_BUNDLE_SCENE)] if name == _BUNDLE_SCENE_ALIAS else []
        source = _BUNDLE_SOURCES[name]
        exec(compile(source, str(origin), "exec"), module.__dict__)

def install_scene_support():
    if not any(isinstance(item, _SceneBundleLoader) for item in _bundle_sys.meta_path):
        _bundle_sys.meta_path.insert(0, _SceneBundleLoader())

install_scene_support()



import pcve_edit_dsl as dsl
from scene_config import load_scenario

BASELINE_PHYSICS = load_scenario()['physics']
# Three bodies carry the five edits: the ball itself, the two corner walls it
# rebounds off, and the world (gravity). Every property here is one whose
# change moves the ball somewhere visibly different in the simulated frames;
# the ball's mass is deliberately absent, because a free sphere under gravity
# with mass-independent contact laws follows the identical trajectory at any
# mass and a mass edit would render as the source video.
OBJECTS = {
    'ball': {'zh': '排球', 'en': 'the volleyball'},
    'wall': {'zh': '墙面', 'en': 'the walls'},
    'world': {'zh': '场景', 'en': 'the scene'},
}
PROPERTIES = {
    'initial_velocity': dsl.PropertySpec('scalar', 'm/s', '初始速度大小', 'initial speed',
        initial_condition=True),
    'restitution': dsl.PropertySpec('scalar', '', '恢复系数', 'restitution'),
    'friction': dsl.PropertySpec('scalar', '', '摩擦系数', 'friction coefficient'),
    # Signed, exactly as the simulator stores it: -9.81 m/s^2 measures 9.81
    # downwards, and doubling the magnitude at a frame is what a timed gravity
    # edit writes into the running solver.
    'gravity': dsl.PropertySpec('scalar', 'm/s²', '重力加速度', 'gravity'),
}
SIM_BINDINGS = {
    ('ball', 'initial_velocity'): dsl.SimBinding('ball_initial_speed'),
    ('ball', 'restitution'): dsl.SimBinding('ball_restitution'),
    ('ball', 'friction'): dsl.SimBinding('ball_friction'),
    ('wall', 'restitution'): dsl.SimBinding('wall_restitution'),
    ('world', 'gravity'): dsl.SimBinding('gravity_z'),
}
# The ball is the only body in the clip; the room, cabinet, plant pot and two
# spare volleyballs are static scenery the ball never touches in this corner
# rebound, so removing any of them would change the picture without changing
# the physics. No DELETE, no ADD, and therefore no delete/add bindings.
DELETE_BINDINGS = {}
VOCAB = dsl.Vocabulary(objects=OBJECTS, properties=PROPERTIES, sim_bindings=SIM_BINDINGS,
    delete_bindings=DELETE_BINDINGS, baseline_physics=BASELINE_PHYSICS, total_frames=96)

# Exactly five edits: three that reshape the ball's own motion, one that makes
# the corner walls absorb the rebound, and one gravity change applied while the
# ball is still in flight so the first half of the clip is the source video.
EDIT_CASES = (
    ('edit_speed_x15', 'SET ball.initial_velocity TIMES 1.5'),
    ('edit_restitution_x03', 'SET ball.restitution TIMES 0.3'),
    ('edit_friction_x05', 'SET ball.friction TIMES 0.5'),
    ('edit_wall_restitution_x04', 'SET wall.restitution TIMES 0.4'),
    ('edit_gravity_x25_at24', 'SET world.gravity TIMES 2.5 AT FRAME 24'),
)
